        val prior = offLoopSellsInFlight7288[ts.mint]
        if (prior != null && now - prior < OFF_LOOP_SELL_RETRY_MS_7288) {
            try { PipelineHealthCollector.labelInc("TICK_SELL_OFF_LOOP_COALESCED_7288") } catch (_: Throwable) {}
            return
