        try {
            com.lifecyclebot.engine.learning.LaneEntryFloorTuner7111.noteApplied7111(
                lane,
                entryScoreTightenedFloor4591Base + qualityWrRaise6044 +
                    moonshotVolumeRelief6044 + streakFloorDelta6961,
