            if (coldStartFloor6984.isFinite() && coldStartFloor6984 < entryScoreTightenedFloor4591Tuned6984) {
                try {
                    PipelineHealthCollector.labelInc("COLD_START_SCORE_FLOOR_APPLIED_6984")
                    ForensicLogger.lifecycle(
                        "COLD_START_SCORE_FLOOR_APPLIED_6984",
                        "lane=$lane tuned=${"%.1f".format(entryScoreTightenedFloor4591Tuned6984)} " +
                            "coldStart=${"%.1f".format(coldStartFloor6984)} " +
                            "threshold=${com.lifecyclebot.engine.ColdStartPriors.COLD_START_TRADE_THRESHOLD} " +
                            "action=use_permissive_prior_until_evidence_exists",
                    )
                } catch (_: Throwable) {}
                coldStartFloor6984
            } else entryScoreTightenedFloor4591Tuned6984
        if (streakFloorDelta6961 > 0.0) {
            try {
                PipelineHealthCollector.labelInc("STREAK_SCORE_FLOOR_RAISED_6961")
                ForensicLogger.lifecycle(
                    "STREAK_SCORE_FLOOR_RAISED_6961",
                    "lane=$lane streak=${try { com.lifecyclebot.engine.truth.ExecutableEntryAuthority6450.consecutiveLossesFor6488(lane) } catch (_: Throwable) { -1L }} " +
                        "delta=+${streakFloorDelta6961.toInt()} base=${"%.1f".format(entryScoreTightenedFloor4591Base)} " +
                        "effective=${"%.1f".format(entryScoreTightenedFloor4591)} sizeUntouched=true reason=fewer_better_not_smaller_same",
                )
            } catch (_: Throwable) {}
        }
        if (qualityWrRaise6044 > 0.0 || moonshotVolumeRelief6044 != 0.0) {
            try {
                PipelineHealthCollector.labelInc("LANE_QUALITY_MOONSHOT_FLOOR_TUNE_6044")
                ForensicLogger.lifecycle("LANE_QUALITY_MOONSHOT_FLOOR_TUNE_6044", "lane=$lane qualityRaise=${"%.1f".format(qualityWrRaise6044)} moonshotRelief=${"%.1f".format(moonshotVolumeRelief6044)} base=${"%.1f".format(entryScoreTightenedFloor4591Base)} tuned=${"%.1f".format(entryScoreTightenedFloor4591Tuned6984)}")
            } catch (_: Throwable) {}
        }
        if (entryScoreTightenedFloor4591 != structuralFloor6020) {
            try {
                PipelineHealthCollector.labelInc("FLUID_SCORE_SCAFFOLD_6020")
                ForensicLogger.lifecycle("FLUID_SCORE_SCAFFOLD_6020", "lane=$lane auth=${agiAuthority6020.name} baseFloor=${"%.0f".format(shapedConfidenceFloor4262)} structural=${"%.0f".format(structuralFloor6020)} effective=${"%.0f".format(entryScoreTightenedFloor4591)} action=soft_start_tighten_then_delegate")
            } catch (_: Throwable) {}
        }
        val crossTalkSizeMult4262 = xTalkShape4262?.sizeMultiplier ?: 1.0
        if (xTalkShape4262 != null) {
            try {
                PipelineHealthCollector.labelInc("MEME_CROSSTALK_ENTRY_SHAPED_4262")
                ForensicLogger.lifecycle("MEME_CROSSTALK_ENTRY_SHAPED_4262", "lane=$lane mint=${mintForProbe.take(10)} ${xTalkShape4262.reason}")
            } catch (_: Throwable) {}
        }
        // V5.0.4206 — revive ChopFilter as a SOFT FDG candidate shaper.
        // The audit item asked for intake use, but hard intake rejection would
        // contradict throughput doctrine and hide samples. laneQualifiedBuyDecision
        // is the shared pre-FDG choke point for all meme lanes, so apply the
        // chop penalty once here by lowering candidate entryScore only. No return,
        // no purge, no slot removal; high-quality chop-source candidates can still
        // pass if their score clears the raised bar.
        val sourceForChop = try { status.tokens[mintForProbe]?.source ?: "" } catch (_: Throwable) { "" }
        val edgeToken4529 = try { status.tokens[mintForProbe] } catch (_: Throwable) { null }
        val edgeSymbol4529 = edgeToken4529?.symbol ?: mintForProbe.take(8)
        val edgeMcap4529 = edgeToken4529?.lastMcap ?: -1.0
