    private fun catastrophicPaperLowScoreSpecialistBleed(ts: com.lifecyclebot.data.TokenState, lane: String): Boolean {
        return try {
            if (!com.lifecyclebot.engine.RuntimeModeAuthority.isPaper()) return false
            val l = lane.uppercase()
            val nonMemeSpecialist = (l == "MANIPULATED" || l == "QUALITY" || l == "DIP_HUNTER"
                || l == "PROJECT_SNIPER" || l == "TREASURY" || l == "BLUECHIP")
            if (!nonMemeSpecialist) return false
            val score = (ts.lastV3Score ?: ts.entryScore.toInt()).coerceIn(-100, 150)
            if (score > 10) return false
            // V5.0.3716/3718 — CATASTROPHIC_PAPER_SPECIALIST_BLEED_GUARD.
            // 3716 used RegimeDetector.current() here, but this method runs per
            // lane and RegimeDetector can synchronously scan TradeHistoryStore on
            // cache expiry. Use the O(1) cached guard instead.
            com.lifecyclebot.engine.CatastrophicPaperBleedGuard.isActive()
        } catch (_: Throwable) { false }
    }

    private fun shouldRunBuyLaneForCycle(ts: com.lifecyclebot.data.TokenState, lane: String, primaryLane: String): Boolean {
        // V5.0.6002 — LANE QUARANTINE (operator directive 2026-07-02).
        // MANIPULATED, PROJECT_SNIPER, DIP_HUNTER are hard-paused for new
        // BUY entries until the LLM Lab autonomously promotes a strategy
        // that targets each lane (≥5 paper trades, ≥50% WR, ≥+0 SOL PnL,
        // strategy name/rationale mentions the lane). Open positions in
        // these lanes ride out untouched; exits still work. Priority:
        // this check runs BEFORE primary-lane override so a bleeder cannot
        // sneak in as primary.
        try {
            if (LaneQuarantineController.isQuarantined(lane)) {
                val paperRuntime6094 = try { RuntimeModeAuthority.isPaper() } catch (_: Throwable) { false }
                if (paperRuntime6094) {
                    try {
                        PipelineHealthCollector.labelInc("PAPER_LANE_QUARANTINE_STILL_SAMPLING_6094_${lane.uppercase()}")
                        // V5.0.6363 — 30s per-lane cooldown on the disk emit. V5.0.6362 snapshot
                        // showed this label firing 4073 times in 55min (74/min). Label counter
                        // still increments every call so frequency data is preserved.
                        if (ForensicEmitRateLimiter6356.shouldEmit("PAPER_LANE_QUARANTINE_STILL_SAMPLING_6094", lane)) {
                            ForensicLogger.lifecycle(
                                "PAPER_LANE_QUARANTINE_STILL_SAMPLING_6094",
                                "lane=$lane symbol=${ts.symbol} mint=${ts.mint.take(10)} primary=$primaryLane reason=paper_enabled_live_quarantined",
                            )
                        }
                    } catch (_: Throwable) {}
                } else {
                    LaneQuarantineController.logBlockedEntry(lane, ts.symbol, ts.mint, primaryLane)
                    return false
                }
            }
        } catch (_: Throwable) { /* quarantine must never break the gate */ }
        // V5.9.1586 — restore 3501 lane behavior. Primary lane is display/default
        // metadata only; it is NOT a pre-FDG execution suppressor. Every enabled
        // lane may evaluate, and FDG receives a candidate only if that lane actually
        // produces BUY/PROBE intent. Runtime lane disable is already a no-op unless
        // an explicit operator policy is added later.
        //
        // V5.9.1561 — fanout collapse must NEVER suppress Standard V3/Core lanes
        // (regression guard: GoldenTapeRegressionTest.fanout_suppression_never_…).
        // The legacy STANDARD/CORE/V3 lanes are the trunk path; any future suppressor
        // must explicitly whitelist them: l == "STANDARD" || l == "CORE" || l == "V3".
        //
        // V5.0.3684 — FANOUT CONTAINMENT (operator deep-audit P1).
        //
        // Diagnosis from the live snapshot:
        //   LANE_EVAL=16084  INTAKE=716  → laneEval/intake = 22.42 (target ≤ 3)
        //   QUALITY=2282, MOONSHOT=2262, SHITCOIN=2248, MANIPULATED=2237,
        //   DIP_HUNTER=2236, PROJECT_SNIPER=2236, TREASURY=2220, BLUECHIP=363
        // All 8 lanes evaluating every meme candidate even with enabled=[MEME].
        // FDG was running multiple times per token → executor starved → 0 live buys.
        //
        // Doctrine:
        //   1. STANDARD/CORE/V3 ALWAYS pass — regression-guarded trunk path.
        //   2. The token's primary lane ALWAYS passes — that's the route the
        //      AgenticStyleRouter chose for this candidate.
        //   3. EnabledTraderAuthority.isMemeLiveOnly() ⇒ suppress every non-meme
        //      specialist (MANIPULATED, QUALITY, DIP_HUNTER, PROJECT_SNIPER,
        //      TREASURY, BLUECHIP). Only MEME-family lanes (SHITCOIN, MOONSHOT)
        //      may evaluate alongside the primary.
        //   4. Mixed/full mode ⇒ allow primary + ONE rescue lane drawn from the
        //      token's intake-affinity set (already capped at 2-4 lanes per
        //      intake by inferIntakeLaneAffinity). The token's affinity set is
        //      the operator's signal that this candidate "looks like" multiple
        //      lane shapes — but we still cap fanout per the operator P1 spec:
        //      "primary lane + at most one rescue lane".
        val l = lane.uppercase()
        val claimedOwner6600 = LaneExecutionCoordinator.currentElection6600(ts.mint)?.primaryLane
        if (!claimedOwner6600.isNullOrBlank() && !claimedOwner6600.equals(l, true)) {
            try { ToolkitSignalSheet.recordDeskStage(l, "CONTRIBUTOR_ONLY", "${ts.mint}:${LaneExecutionCoordinator.candidateVersionFor(ts.mint)}") } catch (_: Throwable) {}
            return false
        }
        // V5.0.6533 — specialist execution is bounded below to primary + one deterministic rescue.
        // Trunk handling occurs after metric-stage hard safety below.
        // canonicalCycleLaneFor elected the owner before these lane sections.
        // Non-primary specialists continue to the bounded rescue election below;
        // they are not unconditionally amputated before affinity/owner policy.
        // L7 LANE EDGE OBSERVATION.
        //
        // V5.0.6876 §A_COUNTER_THAT_CLAIMED_A_THROTTLE_NOBODY_APPLIES — this block
        // used to be headed "L7 WORST-LANE SUPPRESSION" and said it would "suppress
        // these from EVALUATING entirely". It does not, and has not for a long time:
        // the body only calls PipelineHealthCollector.labelInc. V5.0.4300 correctly
        // de-fanged the small-sample case, and the mature case was left emitting
        // L7_LANE_NEGATIVE_EDGE_SHAPED_6613_<lane> — a name asserting shaping by a
        // "6613" authority that does not exist anywhere in the tree.
        //
        // The behaviour is right and is deliberately left alone: suppressing lanes
        // contradicts the standing "never disable a lane / don't disable, re-educate"
        // mandate (V5.9.1358), and bleeding lanes ARE genuinely shaped — by
        // LaneExpectancyDamper (size multiplier plus the V5.0.6838 admission
        // score-floor delta), BleederLaneProbation6747, BandLossVetoGuard and
        // LaneAutoPauseGuard. What was wrong was the label: an operator reading
        // L7_LANE_NEGATIVE_EDGE_SHAPED_6613_SHITCOIN in a dump would conclude that
        // lane was being throttled here, and go looking for a throttle that is not
        // in this file. Same cost as any misleading number — it spends the reader's
        // time. The counters now say what they are and name where the shaping lives.
        if (l in setOf("SHITCOIN", "EXPRESS", "MANIPULATED", "DIP_HUNTER")
            && !l.equals(primaryLane, ignoreCase = true)) {
            try {
                val wr = com.lifecyclebot.engine.LiveLayerGateRelaxer.currentLiveWrPct()
                val liveN = com.lifecyclebot.engine.LiveLayerGateRelaxer.currentLiveTerminalCount()
                if (liveN >= 40 && wr < 45.0) {
                    PipelineHealthCollector.labelInc("L7_LANE_NEGATIVE_EDGE_OBSERVED_6876_$l")
                } else if (liveN < 40 && wr < 45.0) {
                    PipelineHealthCollector.labelInc("L7_LANE_SOFT_START_ALLOWED_4300_$l")
                }
            } catch (_: Throwable) {}
        }
        val metricFit = try { TokenMetricStageRouter.laneFit(ts, l) } catch (_: Throwable) { TokenMetricStageRouter.LaneFit(true, l, TokenMetricStageRouter.Stage.UNKNOWN, "fit_error") }
        if (RuntimeModeAuthority.isLive() && !metricFit.allowed) {
            try {
                ForensicLogger.lifecycle("TOKEN_METRIC_STAGE_LANE_SOFT_MISMATCH_4162", "lane=$l primary=$primaryLane symbol=${ts.symbol} mint=${ts.mint.take(10)} ${metricFit.reason}")
                PipelineHealthCollector.labelInc("TOKEN_METRIC_STAGE_LANE_SOFT_MISMATCH_${metricFit.stage.name}")
            } catch (_: Throwable) {}
            // V5.0.4162 — stage mismatch is not a lane veto. Runtime showed
            // DIP_HUNTER primaries suppressing every other MemeTrader lane before
            // FDG/intent, so all-lanes-enabled was cosmetic. Keep true rug-prone
            // stage as hard safety; otherwise let the lane express intent and let
            // FDG/sizing handle risk.
            if (metricFit.stage == TokenMetricStageRouter.Stage.RUG_PRONE) return false
        }
        // V5.0.6533 — trunk is causal after quarantine/rug safety, before specialist ownership.
        if (ExecutionAuthorityPolicy6533.isTrunkLane(l)) return true
        val designatedDeskSheet6599 = try { ToolkitSignalSheet.snapshot(ts) } catch (_: Throwable) { null }
        val designatedDeskHypothesis6599 = designatedDeskSheet6599?.deskHypotheses?.get(l)
        // V5.0.7297 — the lane's own hunt is its desk hypothesis for this token.
        val huntedByLane7297 = try {
            val claim7301 = com.lifecyclebot.engine.market.LaneHunter7297.claimFor(ts.mint, ts.lastMcap)
            claim7301.equals(l, ignoreCase = true) || (claim7301 == "CASHGEN" && l.equals("TREASURY", ignoreCase = true))
        } catch (_: Throwable) { false }
        val designatedDeskQualified6599 = designatedDeskSheet6599 == null || designatedDeskSheet6599.deskHypotheses.isEmpty() || designatedDeskHypothesis6599 != null || huntedByLane7297
        val candidateVersion6600 = LaneExecutionCoordinator.candidateVersionFor(ts.mint)
        val qualifiedDeskLanes6600 = designatedDeskSheet6599?.deskHypotheses?.keys.orEmpty().filter { !ExecutionAuthorityPolicy6533.isTrunkLane(it) }
        val boundedRescue6600 = ExecutionAuthorityPolicy6533.selectOneRescue(
            mint = ts.mint,
            candidateVersion = candidateVersion6600,
            primaryLane = primaryLane,
            affinityLanes = ts.laneAffinity,
            eligibleLanes = qualifiedDeskLanes6600,
        )
        val specialistEvaluationAllowed6600 = designatedDeskQualified6599 &&
            (l.equals(primaryLane, true) || l.equals(boundedRescue6600, true))
        // V5.0.6604 §SPECIALIST_CONSENSUS_GATE (troubleshoot_agent P0 fix).
        //   Root cause slice of the <10% MemeTrader WR: MEME specialists
        //   (SHITCOIN / EXPRESS / MOONSHOT / PROJECT_SNIPER) could satisfy
        //   `designatedDeskQualified6599` and become primary/rescue while
        //   BrainConsensusGate would independently HARD_BLOCK the same
        //   candidate downstream. But because the specialist was already
        //   the elected desk, capital was already committed to the buy
        //   path; the downstream veto only reshaped the trade instead of
        //   preventing it. Fix: hoist the two strongest binding signals
        //   (proven-dead HARD_BLOCK equivalent + AUTHORITATIVE lane pWin
        //   floor) into the specialist election itself for MEME lanes.
        //   • provenDeadHardBlock6604: mirror BrainConsensusGate's
        //     proven-dead classifier (`LosingPatternMemory.isDangerZone`
        //     with a non-trivial sample) — this is the same input BCG
        //     uses to emit its HARD_BLOCK verdict.
        //   • lanePWinBelowGate6604: when the lane's own head has
        //     graduated to AUTHORITATIVE, require predictWinProb ≥
        //     SPECIALIST_MIN_PWIN_6604 (0.45). Below that, the head
        //     itself says this candidate loses — specialist affinity
        //     is not enough to override a learned negative signal.
        //   Both are lane-rotational, never lane-disabling: when the
        //   bucket recovers (rotation heals danger-zone stats, head pWin
