                try {
                    val srcUpper6912 = joinedSources.uppercase()
                    val isPumpFun6912 = srcUpper6912.contains("PUMP_FUN") ||
                        srcUpper6912.contains("PUMP_PORTAL") ||
                        srcUpper6912.contains("PUMPFUN")
                    if (isPumpFun6912 &&
