                        // crash or a disabled hive does not silently start a
                        // 60s blackout for this mint.
                        try { tokenMintLastUploadedMs[mint] = System.currentTimeMillis() } catch (_: Throwable) {}
                    } catch (_: Throwable) {
                    } finally {
