            // V5.0.6421 — skip on slow cycles (see PRE_SUPERVISOR_LEARNING_SKIPPED_6421).
            if (!prevCycleWasSlow6421) {
                try {
                    com.lifecyclebot.engine.truth.PreSupervisorBudgetGuard6437.runBudgeted("LabUniverseTick") {
                        runLabUniverseTick()
