    private fun isCapCountableLiveToken(mint: String, ts: com.lifecyclebot.data.TokenState? = null): Boolean {
        return try {
            if (mint.isBlank()) return false
            val hostTracked = com.lifecyclebot.engine.HostWalletTokenTracker.hasTrackedPosition(mint)
            if (hostTracked) return com.lifecyclebot.engine.HostWalletTokenTracker.isCapCountable(mint)
            val pos = ts?.position ?: status.tokens[mint]?.position ?: return false
            !pos.isPaperPosition && pos.qtyToken > 0.0 && pos.isOpen
        } catch (_: Throwable) { false }
    }

    private fun reapGhostForcedOpen(forcedOpenRaw: List<String>): List<String> {
        try { com.lifecyclebot.engine.PositionCloseLedger.prune() } catch (_: Throwable) {}
        // Build the authoritative live-open set ONCE (close ledger + live TokenState
        // + sub-trader stores were already unioned into forcedOpenRaw, but a mint can
        // be in forcedOpenRaw yet no longer report open anywhere — that's a ghost).
        val liveOpenSet: Set<String> = try {
            val out = HashSet<String>()
            synchronized(status.tokens) {
                status.tokens.values.forEach { if (isCapCountableLiveToken(it.mint, it)) out.add(it.mint) }
            }
            forcedOpenRaw.forEach { m -> if (com.lifecyclebot.engine.GlobalTradeRegistry.hasOpenPosition(m)) out.add(m) }
            out
        } catch (_: Throwable) { forcedOpenRaw.toSet() }

        val reaped = forcedOpenRaw.filter { isGhostMint(it, liveOpenSet) }
        if (reaped.isNotEmpty()) {
            try {
                ForensicLogger.lifecycle("GHOST_POSITION_REAPED", "count=${reaped.size} mints=${reaped.take(8).joinToString(",") { it.take(8) }}")
                com.lifecyclebot.engine.PipelineHealthCollector.labelInc("GHOST_POSITION_REAPED")
            } catch (_: Throwable) {}
            for (m in reaped) {
                try { com.lifecyclebot.engine.Executor.releasePaperSellLock(m) } catch (_: Throwable) {}
                try { supervisorForceReleaseLeaseAndCancel(m, "GHOST_REAP") } catch (_: Throwable) {}
                // V5.9.1498 — ROOT-CAUSE: evict the stale entry from the sub-trader
                // stores so getActivePositions()/getActiveDips()/getActiveRides()
                // stop re-emitting it into forcedOpenRaw next cycle. WITHOUT this,
                // a closed mint is reaped (lease released) but immediately re-added
                // from the store on the very next cycle → ghost>0 forever → every
                // buy defers (the 6h-dead park). Pure map removal, no PnL/learning.
                evictSubTraderGhost(m)
            }
        }
        // Stash the clean list + live set so publishSlotHealth counts the SAME truth.
        lastReapLiveOpenSet = liveOpenSet
        return forcedOpenRaw.filterNot { isGhostMint(it, liveOpenSet) }
    }

    @Volatile private var lastReapLiveOpenSet: Set<String> = emptySet()

    private fun publishSlotHealth(forcedOpenClean: Collection<String>, forcedOpenCount: Int) {
        // V5.9.1475 (spec item 3) — count ghosts from the CLEANED forcedOpen list
        // using the SAME canonical predicate the reaper used. Previously this was
        // passed the RAW (pre-reap) list and re-counted just-reaped mints as ghosts,
        // so ghost never fell to 0 even though reaping happened. After reaping, a
        // healthy steady state has ghost=0.
        val live = lastReapLiveOpenSet
        val paperRuntime = try { RuntimeModeAuthority.isPaper() } catch (_: Throwable) { try { ConfigStore.load(applicationContext).paperMode } catch (_: Throwable) { false } }
        val ghostOpenNow = if (paperRuntime) 0 else forcedOpenClean.count { isGhostMint(it, live) }
        val paperLedgerOpenMints7084 = if (paperRuntime) currentPaperOpenMintsFromLedger() else emptySet()
        val paperOpenNow = if (paperRuntime) paperLedgerOpenMints7084.size else forcedOpenCount
        // V5.0.7084 §"forced" WAS A SECOND COUNT OF OPEN POSITIONS.
        //
        // Operator directive §4 targets `forced=34 open=40` and asks for
        // "forced < 5", treating it as slot-cleanup lag. It is not lag. In PAPER
        // runtime this call site passed the SAME QUANTITY to both parameters:
        //
        //     forcedOpen    = currentPaperOpenMintsFromLedger().size
        //     openPositions = currentPaperOpenMintsFromLedger().size
        //
        // SlotHealthGate.publish then rebuilt `open` from
        // CanonicalPositionAuthority6441.activeMintProjections6490("paper") and
        // left `forced` as the raw ledger count, clamped to it. So 34 vs 40 is
        // not forced-versus-open at all — it is TWO VIEWS OF THE OPEN BOOK
        // disagreeing by six, with the smaller one printed under a name that
        // means "stuck".
        //
        // That makes the directive's target unreachable by construction: while
        // the bot legitimately holds 34 paper positions, `forced` cannot fall
        // below 5 no matter how perfectly cleanup runs. Any work aimed at the
        // number would have been chasing a quantity that was never measuring
        // the thing it is named after — the defect class that has produced the
        // most wasted effort in this codebase.
        //
        // WHAT FORCED SHOULD MEAN, and now does: ledger-open mints that the
        // canonical authority does NOT consider active. A position that closed
        // and released its slot leaves this set immediately; one that is stuck
        // stays in it. That is exactly the directive's own definition — "a
        // CLOSED/QUARANTINED/non-open position must release its slot
        // immediately after canonical commit" — expressed as a set difference
        // rather than a subtraction of two counts.
        //
        // NO BEHAVIOUR CHANGE IN PAPER. V5.0.6692 already made forced
        // fail-open for paper runtime (SlotHealthGate:199 emits
        // PAPER_FORCED_OPEN_ADVISORY_6709 and deliberately does not defer), so
        // paper buy admission is untouched. Turnover is still governed solely
        // by 6709's adaptive cadence, which stays non-zero at every level. For
        // LIVE runtime the existing deferral semantics are unchanged but now
        // read a number that means what it says.
        val paperForcedStale7084 = if (paperRuntime) {
            try {
                val canonicalActive = com.lifecyclebot.engine.truth.CanonicalPositionAuthority6441
                    .activeMintProjections6490("paper")
                    .map { it.mint }
                    .toSet()
                val stale = paperLedgerOpenMints7084.filterNot { it in canonicalActive }
                if (stale.isNotEmpty()) {
                    try {
                        com.lifecyclebot.engine.PipelineHealthCollector.labelInc("PAPER_SLOT_FORCED_IS_STALE_HOLD_7084")
                        com.lifecyclebot.engine.ForensicLogger.lifecycle(
                            "PAPER_SLOT_FORCED_IS_STALE_HOLD_7084",
                            "ledgerOpen=${paperLedgerOpenMints7084.size} canonicalActive=${canonicalActive.size} " +
                                "staleHolds=${stale.size} mints=${stale.take(8).joinToString(",") { it.take(8) }} " +
                                "action=forced_now_counts_only_slots_canonical_does_not_hold",
                        )
                    } catch (_: Throwable) {}
                }
                stale.size
            } catch (_: Throwable) { 0 }
        } else forcedOpenCount
        val exitInFlight = try { fullExitSweepPending.get() || universalSlSweepPending.get() } catch (_: Throwable) { false }
        com.lifecyclebot.engine.SlotHealthGate.publish(
            ghostOpen = ghostOpenNow,
            forcedOpen = paperForcedStale7084,
            openPositions = if (paperRuntime) paperOpenNow else forcedOpenCount,
            supActive = supervisorActive.get(),
            supCap = supervisorEffectiveCap(),
            exitInFlight = exitInFlight,
        )
    }

    private fun supervisorEffectiveCap(): Int {
        val base = SUPERVISOR_BASE_MAX_WORKERS
        val now = System.currentTimeMillis()
        // Count timeouts in the current 10-min window (maintained by the throttle note fn).
        val windowFresh = (now - supervisorTimeoutWindowStartMs) < 600_000L
        val timeouts = if (windowFresh) supervisorTimeoutWindowCount else 0
        // COOLING latch: >500/10min trips a 60s cooling window (concurrent cap halved, min 8).
        // V5.0.6308a — supervisorCoolingUntilMs is now anchored to
        // SystemClock.elapsedRealtime() (monotonic, immune to NTP steps).
        // Convert the timeout-driven cooling write to the same timebase.
        val nowMono = android.os.SystemClock.elapsedRealtime()
        if (timeouts >= 150) supervisorCoolingUntilMs = nowMono + 90_000L
        // V5.0.6362 — RE-ARMED emergency throttle. Was `V5.9.1332: clamp removed;
        // observation-only`. Operator's V5.0.6361 snapshot showed 300+ worker timeouts
        // per 10min while the throttle was still just logging. Now
        // supervisorEmergencyThrottleUntilMs is consulted and the effective cap is
        // clamped to SUPERVISOR_EMERGENCY_MAX_WORKERS while the arm window is active.
        // Cooling still runs on top; the stricter floor wins. Exit dispatcher is
        // unaffected (runs on its own pool).
        //
        // Tier semantics (preserved in SupervisorEmergencyThrottle6362.effectiveCap):
        //   emergency arm  -> maxOf(8, SUPERVISOR_EMERGENCY_MAX_WORKERS)
        //   cooling        -> maxOf(8, base / 3)
        //   timeouts >= 150 -> maxOf(8, base / 3)   // heavy: drain debt first
        //   timeouts >= 30  -> maxOf(12, base / 2)  // moderate tier
        //   else           -> base
        return SupervisorEmergencyThrottle6362.effectiveCap(
            base = base,
            emergency = SUPERVISOR_EMERGENCY_MAX_WORKERS,
            nowMonoMs = nowMono,
            coolingUntilMs = supervisorCoolingUntilMs,
            emergencyThrottleUntilMs = supervisorEmergencyThrottleUntilMs,
            timeouts = timeouts,
        )
    }
    // V5.9.1319 (Item 3) — emergency-throttle arming. When sustained overload is detected
    // (a cycle exceeding 30s, OR >20 worker timeouts inside a 10-minute window) we clamp the
    // effective worker cap to 16 and shorten cycle pressure for the next 5 minutes. Exit
    // protection (ExitCoordinator) is unaffected — it runs on its own dispatcher.
    @Volatile private var supervisorTimeoutWindowStartMs: Long = 0L
    @Volatile private var supervisorTimeoutWindowCount: Int = 0
    private fun supervisorArmEmergencyThrottle(reason: String, detail: String) {
        // V5.0.6362 — RE-ARMED. Was V5.9.1332 no-op observation. Operator's
        // V5.0.6361 snapshot: 300+ worker timeouts per 10min while the throttle
        // was still just logging → cycles ballooned past 200s under heavy intake.
        // Now the arm writes a 5-minute clamp window; supervisorEffectiveCap
        // consults it via SupervisorEmergencyThrottle6362.effectiveCap and drops
        // the worker cap to SUPERVISOR_EMERGENCY_MAX_WORKERS while active.
        try {
            val nowMono = android.os.SystemClock.elapsedRealtime()
            // V5.0.6436 §1 — STATE-TRANSITION emission. Operator: "arming
            // must be state-transition based: UNARMED → ARMED = one event.
            // Do not re-emit ARMED once per expired worker." Capture the
            // pre-call throttle window state so we only fire the ARMED
            // forensic event when we actually transition from unarmed
            // (no active window OR expired) to armed (future window).
            val wasArmed6436 = supervisorEmergencyThrottleUntilMs > nowMono
            supervisorEmergencyThrottleUntilMs = SupervisorEmergencyThrottle6362.armUntil(
                nowMonoMs = nowMono,
                existingUntilMs = supervisorEmergencyThrottleUntilMs,
            )
            val nowArmed6436 = supervisorEmergencyThrottleUntilMs > nowMono
            if (!wasArmed6436 && nowArmed6436) {
                ForensicLogger.lifecycle(
                    "SUPERVISOR_EMERGENCY_THROTTLE_ARMED_6362",
                    "reason=$reason $detail cap=$SUPERVISOR_EMERGENCY_MAX_WORKERS windowMs=300000",
                )
                try { PipelineHealthCollector.labelInc("SUPERVISOR_EMERGENCY_THROTTLE_ARMED_6362") } catch (_: Throwable) {}
            } else if (wasArmed6436 && nowArmed6436) {
                // Already armed — count the extend but do not spam the
                // ARMED transition event.
                try { PipelineHealthCollector.labelInc("SUPERVISOR_EMERGENCY_THROTTLE_EXTENDED_6436") } catch (_: Throwable) {}
            }
        } catch (_: Throwable) {}
    }
    private fun supervisorNoteWorkerTimeoutForThrottle() {
        val now = System.currentTimeMillis()
        if (now - supervisorTimeoutWindowStartMs >= 600_000L) {
            supervisorTimeoutWindowStartMs = now
            supervisorTimeoutWindowCount = 0
        }
        supervisorTimeoutWindowCount += 1
        // V5.9.1331 — STALL FIX (operator: "still trade stalls. it should never not be intake tokens").
        // The 20-timeout-in-10min trip was over-firing under the new ~2800/day throughput
        // (each cycle touches 32 tokens × 6/min = 192/min; even a 1% slow-API rate yields
        // ~2 timeouts/min = 120/10min — way above 20). Result: emergency throttle cap=16
        // pins for 5min repeatedly, cutting effective throughput in half during the
        // exact window when intake should be highest. Raise threshold 20→60 so the
        // throttle only kicks in on REAL pool exhaustion, not normal API tail latency.
        if (supervisorTimeoutWindowCount >= 30) {
            supervisorArmEmergencyThrottle("worker_timeouts", "count=$supervisorTimeoutWindowCount/10min")
        }
    }
    fun supervisorNoteCycleElapsedForThrottle(cycleMs: Long) {
        // V5.0.6072 — throttle arms at 15s (was 30s). Operator report showed
        // avgCycle=9552ms max=77422ms; waiting for 6× the 5s cycle budget
        // before cooling let wedged-IO bursts compound for multiple cycles.
        //
        // V5.0.6308 — RE-ARMED (V5.9.1332 disarm bug fix). Operator's emergency
        // fallback report showed cycles at avg=36s / max=232s with cycles
        // over 77s WITHOUT actually clamping.
        //
        // V5.0.6364 — REMOVED cycle-time arm trigger (SOURCE OF THE
        // SELF-REINFORCING LOOP).
        // Operator directive: "the fixes need to be at the source of creation not
        // a bandaid patch." V5.0.6363 emergency snapshot showed 2099 arms in
        // 96min (one every ~3s) with rolling 50 WR crashing 80% → 32%.
        // The cycle-time arm was a positive-feedback governor:
        //   slow main-loop cycle -> arm 5min clamp -> workers drop to 16
        //     -> exits starve waiting on the tiny pool -> next cycle even
        //     slower -> another arm -> permanent clamp.
        // The clamp itself was correct for its ORIGINAL trigger (worker
        // timeouts = pool saturation). Cycle time is a main-thread symptom,
        // NOT a worker-pool symptom; clamping workers can never help. The
        // cooling latch below is retained because it applies its own tighter
        // window, not the emergency clamp.
        // Worker-timeout arm path (supervisorNoteWorkerTimeoutForThrottle)
        // is UNCHANGED — it still arms on 30+ real worker timeouts / 10min.
        // V5.0.6308a — R2 fix (testing agent iter_5). Use SystemClock.elapsedRealtime
        // instead of wall clock so NTP steps can't collapse or extend the cooling
        // window arbitrarily. Cooling window is now DYNAMIC = max(base, cycleMs*1.5)
        // so a 232s cycle gets ~348s cooling (was 120s → cap re-opened mid-stall).
        val now = android.os.SystemClock.elapsedRealtime()
        when {
            cycleMs > 90_000L -> {
                val coolMs = maxOf(120_000L, (cycleMs * 3L) / 2L)
                supervisorCoolingUntilMs = maxOf(supervisorCoolingUntilMs, now + coolMs)
                try { ForensicLogger.lifecycle("SUPERVISOR_COOLING_ARMED_6308", "reason=cycle_over_90s cycleMs=$cycleMs coolingForMs=$coolMs") } catch (_: Throwable) {}
                try { PipelineHealthCollector.labelInc("SUPERVISOR_COOLING_ARMED_HEAVY_6308") } catch (_: Throwable) {}
            }
            cycleMs > 30_000L -> {
                val coolMs = maxOf(60_000L, (cycleMs * 3L) / 2L)
                supervisorCoolingUntilMs = maxOf(supervisorCoolingUntilMs, now + coolMs)
                try { ForensicLogger.lifecycle("SUPERVISOR_COOLING_ARMED_6308", "reason=cycle_over_30s cycleMs=$cycleMs coolingForMs=$coolMs") } catch (_: Throwable) {}
                try { PipelineHealthCollector.labelInc("SUPERVISOR_COOLING_ARMED_LIGHT_6308") } catch (_: Throwable) {}
            }
        }
    }
    @Suppress("unused") private val SUPERVISOR_MAX_LIVE_WORKERS: Int = 32

    // V5.9.1073 — SUPERVISOR ACCOUNTING REWRITE.
    // Operator directive: give supervisor a range of 100 and stop the repeated
    // active=48/cap=48 weirdness. The old design selected 96 mints but allowed
    // only 48 in-flight workers, guaranteeing deferred work on a normal ~100-token
    // universe. Worse, the old stall watchdog "fixed" saturation by setting
    // supervisorActive=0 while workers were still alive; late releases could then
    // push the counter negative/phantom and the next cycle would oscillate between
    // false headroom and cap saturation.
    //
    // V5.9.1149 — align lease cap with the existing live-worker ceiling.
    // Runtime 5.0.3115 showed WATCHLIST_RR picked=199, supervisor spawned=120,
    // skipped=80, active=100 cap=100 liveCap=140. That means admission was still
    // being throttled by the older lease cap while the explicit runaway guard
    // already allowed 140 live workers. Raising the lease cap to 140 restores
    // throughput without scanner pruning, lane disabling, or increasing the
    // selected watchlist pool.
    // Saturation is telemetry only (SUPERVISOR_POOL_SATURATED_NO_RESET); we never
    // destructively reset the active counter again, and stale leases expire before
    // the next 5s loop cadence.
    private val supervisorLastSpawnAt = java.util.concurrent.atomic.AtomicLong(System.currentTimeMillis())
    private val supervisorLifetimeSaturationEvents = java.util.concurrent.atomic.AtomicLong(0) // saturation telemetry counter
    private val SUPERVISOR_POOL_STALL_MS: Long = 8_000L  // telemetry threshold only; no destructive counter reset
    // V5.9.1424 — DOUBLE SUPERVISOR CONCURRENCY 32 → 64 (operator: "its really
    // only trading 1 token at a time ... it'll take months just to bootstrap").
    // Root cause of low concurrent opens: only 32 mints/cycle reached a worker, and
    // a large share of those were blocked (FDG/PROBE_ONLY, REENTRY_LOCKOUT) or
    // open-then-die, so distinct survivable opens per tick were a trickle. Doubling
    // the per-cycle worker pool widens the funnel so more NON-locked, FDG-passing
    // candidates reach EXEC each cycle and can coexist as concurrent positions —
    // the sample-size lever the bootstrap maturity curve needs (doctrine: throughput
    // before cleverness). Does NOT touch the protected 500-token intake pool, the
    // 10-min re-entry lockout, or any safety floor; it only processes more of the
    // already-admitted watchlist per tick. Workers remain bounded + leased, so this
    // cannot leak capacity (hard-expiry cleanup still applies).
    @Suppress("unused") private val SUPERVISOR_MAX_INFLIGHT: Int = 24  // V5.0.3676 — pressure-safe floor. Kept for overloaded/cooling windows.
    private val SUPERVISOR_HEALTHY_MEME_MAX_INFLIGHT: Int = 48  // V5.0.3723 — source fix: when workerTimeout/lease debt is clean, sample the meme hot pool at the real healthy worker cap instead of the old pressure floor.
    // Worker slot budget is one bot-loop cadence: long enough for normal
    // processTokenCycle, short enough that stuck IO cannot hold a supervisor
    // slot across multiple 5s cycles.
    // V5.9.1445 — 5s->8s. 5.0.3447 showed 668 SUPERVISOR_LEASE_FORCE_RELEASED in
    // 302s, nearly all at afterMs=5750 (timeout+watchdog grace) — admitted workers
    // were being force-killed at the 5s wall before processTokenCycle finished,
    // because current API latency (groq 944ms rate-limited, geckoterminal 372ms,
    // pumpfun 766ms) pushes per-token p95 past 5s. 8s lets real work complete while
    // still bounding stuck IO well inside the cycle cadence. workerTimeout=15 (real
    // timeouts) vs 668 force-releases proves most workers were NOT genuinely stuck.
    // V5.0.6366 — 9s -> 15s. Operator emergency snapshot showed 246
    // worker timeouts / 10 min at afterMs=9750, triggering the correct
    // emergency-throttle worker-timeout arm (cap=16) and starving intake
    // to 5 execs in 15 min. Root cause: current external API p95 (Jupiter,
    // Birdeye, DexScreener, Groq under rate-limit) frequently pushes past
    // 9 s. Raising to 15 s lets those calls complete instead of being
    // force-released and re-queued 90s later via supervisorTimeoutCooldown,
    // which was the main drag on wallet growth per operator directive.
    // Cooling latch cap-drop still applies if the raise itself isn't enough.
    private val SUPERVISOR_WORKER_TIMEOUT_MS: Long = 15_000L
    // V5.9.1180 — timeout quarantine is per-mint, not global scanner pruning.
    // 3145 showed workerTimeout=239 while WATCHLIST_RR kept reselecting the
    // same slow/no-pair/API-wedged mints. Re-spawning those mints every 5s burns
    // supervisor slots and creates INFLIGHT_CAP without increasing FDG/EXEC.
    // Non-open timed-out mints cool briefly; open positions bypass this so exits
    // and hard-floor protection remain unconditional.
    private val supervisorTimeoutCooldownUntil = java.util.concurrent.ConcurrentHashMap<String, Long>()
    private val SUPERVISOR_TIMEOUT_COOLDOWN_MS: Long = 90_000L

    private fun supervisorMintIsOpen(mint: String): Boolean = try {
        isCapCountableLiveToken(mint, status.tokens[mint]) ||
            status.openPositions.any { it.mint == mint && isCapCountableLiveToken(it.mint, it) }
    } catch (_: Throwable) { false }

    private fun supervisorTimeoutCooldownActive(mint: String, now: Long = System.currentTimeMillis()): Boolean {
        // V5.9.1572 — open mints no longer bypass supervisor timeout cooldown.
        // Exits are handled by ExitCoordinator/open-position tick, so skipping full
        // supervisor re-poll for a chronic open mint does NOT weaken hard-floor exits.
        // It prevents the same open mints from monopolising every worker slot.
        val until = supervisorTimeoutCooldownUntil[mint] ?: return false
        if (until <= now) {
            supervisorTimeoutCooldownUntil.remove(mint, until)
            return false
        }
        return true
    }

    private fun supervisorArmTimeoutCooldown(mint: String) {
        val open = supervisorMintIsOpen(mint)
        val cooldownMs = if (open) 45_000L else SUPERVISOR_TIMEOUT_COOLDOWN_MS
        val until = System.currentTimeMillis() + cooldownMs
        supervisorTimeoutCooldownUntil[mint] = until
        if (supervisorTimeoutCooldownUntil.size > 2048) {
            val now = System.currentTimeMillis()
            try {
                val it = supervisorTimeoutCooldownUntil.entries.iterator()
                while (it.hasNext()) {
                    val e = it.next()
                    if (e.value <= now) it.remove()
                }
            } catch (_: Throwable) {}
        }
    }

    private fun supervisorPruneExpiredLeases(reason: String = "cycle"): Int {
        val nowMonotonic = android.os.SystemClock.elapsedRealtime()
        var expired = 0
        try {
            val it = supervisorLeases.entries.iterator()
            while (it.hasNext()) {
                val e = it.next()
                val lease = e.value
                val age = nowMonotonic - lease.startedMonotonicMs
                val sinceProgress = nowMonotonic - lease.lastProgressMs.get()
                val job = lease.jobRef.get()
                val genuinelyStuck6616 = age >= SUPERVISOR_LEASE_TTL_MS &&
                    sinceProgress >= SUPERVISOR_LEASE_PROGRESS_TTL_MS && job?.isActive == true
                if (genuinelyStuck6616) {
                    try { job?.cancel() } catch (_: Throwable) {}
                    if (supervisorLeases.remove(e.key, lease)) expired++
                }
            }
        } catch (_: Throwable) {}
        if (expired > 0) {
            supervisorLifetimeExpiredLeases.addAndGet(expired.toLong())
            supervisorActive.set(supervisorLeases.size)
            try {
                ForensicLogger.lifecycle(
                    "SUPERVISOR_LEASE_EXPIRED",
                    "reason=$reason expired=$expired active=${supervisorLeases.size} ttlMs=$SUPERVISOR_LEASE_TTL_MS total=${supervisorLifetimeExpiredLeases.get()}",
                )
            } catch (_: Throwable) {}
        }
        return expired
    }

    private fun supervisorTryAcquireSlot(mint: String): Long {
        supervisorPruneExpiredLeases("acquire")
        val live = supervisorLeases.size
        // Lease cap controls cycle coverage; live-worker cap prevents runaway
        // non-cooperative processTokenCycle calls if APIs wedge.
        // V5.9.1319 (Item 3) — admit against the EFFECTIVE adaptive cap (base 32, or 16
        // during an emergency-throttle window). Replaces the old fixed 140 firehose.
        if (live >= supervisorEffectiveCap()) return -1L
        val id = supervisorLeaseSeq.incrementAndGet()
        supervisorLeases[id] = SupervisorLease(mint = mint, startedMonotonicMs = android.os.SystemClock.elapsedRealtime(), leaseId = id)
        supervisorActive.set(supervisorLeases.size)
        return id
    }

    private fun supervisorReleaseSlot(leaseId: Long): Int {
        if (leaseId > 0L) supervisorLeases.remove(leaseId)
        val active = supervisorLeases.size.coerceAtLeast(0)
        supervisorActive.set(active)
        return active
    }

    private fun supervisorLeaseProgress6448(leaseId: Long, state: String) {
        try {
            val l = supervisorLeases[leaseId] ?: return
            l.lastProgressMs.set(android.os.SystemClock.elapsedRealtime())
            l.completionState.set(state.take(40))
            if (l.threadName.get().isBlank()) l.threadName.set(Thread.currentThread().name.take(80))
        } catch (_: Throwable) {}
    }

    private fun supervisorTimeoutDetail6448(leaseId: Long, mint: String): String {
        val nowMonotonic = android.os.SystemClock.elapsedRealtime()
        val l = supervisorLeases[leaseId]
        val job = try { l?.jobRef?.get() } catch (_: Throwable) { null }
        val started = l?.startedMonotonicMs ?: nowMonotonic
        val last = l?.lastProgressMs?.get() ?: started
        return "leaseId=${l?.leaseId ?: leaseId} mint=${mint.take(10)} task=${l?.task ?: "processTokenCycle"} phase=${l?.phase ?: "SUPERVISOR"} callsite=${l?.acquisitionCallsite ?: "fireSupervisorWorkers"} startedMonotonicMs=$started elapsedMs=${(nowMonotonic-started).coerceAtLeast(0L)} lastProgressMonotonicMs=$last sinceProgressMs=${(nowMonotonic-last).coerceAtLeast(0L)} dispatcher=${l?.dispatcher ?: "Dispatchers.IO"} thread=${l?.threadName?.get().orEmpty()} job=${job?.toString()?.take(80).orEmpty()} cancelling=${job?.isCancelled ?: false} completed=${job?.isCompleted ?: false} state=${l?.completionState?.get().orEmpty()}"
    }

    /**
     * V5.9.1470 (spec item 6) — force-release every lease for a mint AND cancel its
     * worker coroutine. Used by the ghost reaper so reaped/closed mints cannot leave a
     * wedged worker running that re-adds stale state. Idempotent + fail-open. NEVER
     * touches positions/balances — it only cancels a stuck IO coroutine and frees slots.
     */
    private fun supervisorForceReleaseLeaseAndCancel(mint: String, reason: String) {
        if (mint.isBlank()) return
        var cancelled = 0
        try {
            val it = supervisorLeases.entries.iterator()
            while (it.hasNext()) {
                val e = it.next()
                if (e.value.mint == mint) {
                    val lease = e.value
                    val nowMonotonic = android.os.SystemClock.elapsedRealtime()
                    val age = nowMonotonic - lease.startedMonotonicMs
                    val sinceProgress = nowMonotonic - lease.lastProgressMs.get()
                    val job = lease.jobRef.get()
                    val genuinelyStuck6616 = age >= SUPERVISOR_LEASE_TTL_MS &&
                        sinceProgress >= SUPERVISOR_LEASE_PROGRESS_TTL_MS && job?.isActive == true
                    if (genuinelyStuck6616) {
                        try { job?.cancel() } catch (_: Throwable) {}
                        if (supervisorLeases.remove(e.key, lease)) cancelled++
                    } else if (age < SUPERVISOR_LEASE_TTL_MS) {
                        try { com.lifecyclebot.engine.PipelineHealthCollector.labelInc("SUPERVISOR_FORCE_RELEASE_DEFERRED_YOUNG_6616") } catch (_: Throwable) {}
                    }
                }
            }
        } catch (_: Throwable) {}
        if (cancelled > 0) {
            supervisorActive.set(supervisorLeases.size.coerceAtLeast(0))
            // V5.0.6315 — ATOMIC FORCE-RELEASE (§15). Cancelling the
            // supervisor lease alone left the ExecutionAttemptLease + sell
            // execution locks dangling for 5+ minutes, so the retry that
            // followed a WORKER_TIMEOUT was still blocked by the stale
            // exec-lease → the operator saw 96 SUPERVISOR_LEASE_FORCE_RELEASED
            // while the intake side kept flagging 'mint locked'. Mirror the
            // cancel atomically across every downstream lock map we own.
            try { com.lifecyclebot.engine.ExecutionAttemptLease.forceReleaseForMint(mint, reason) } catch (_: Throwable) {}
            try { com.lifecyclebot.engine.sell.SellExecutionLocks.release(mint) } catch (_: Throwable) {}
            try {
                ForensicLogger.lifecycle("SUPERVISOR_LEASE_FORCE_RELEASED", "mint=${mint.take(10)} reason=$reason cancelledJobs=$cancelled active=${supervisorLeases.size} cooled=true")
                com.lifecyclebot.engine.PipelineHealthCollector.labelInc("SUPERVISOR_LEASE_FORCE_RELEASED")
            } catch (_: Throwable) {}
        }
    }

    private fun supervisorClampIfNegative(reason: String) {
        val cur = supervisorActive.get()
        if (cur < 0 && supervisorActive.compareAndSet(cur, 0)) {
            try {
                ForensicLogger.lifecycle(
                    "SUPERVISOR_ACTIVE_CLAMPED",
                    "reason=$reason prevActive=$cur cap=$SUPERVISOR_MAX_INFLIGHT",
                )
            } catch (_: Throwable) {}
        }
        supervisorPruneExpiredLeases(reason)
        supervisorActive.set(supervisorLeases.size.coerceAtLeast(0))
    }

    /**
     * V5.9.1037 — fire-and-forget supervisor. Replaces the chunk-await
     * loop in runSupervisorPhase. Each mint that fits within the
     * SUPERVISOR_MAX_INFLIGHT budget gets a service-owned worker on the
     * bounded entry dispatcher; the rest are deferred to the next
     * cycle's fresh ordering). The bot loop returns immediately — no
     * chunked await, no per-chunk timeout, no SUPERVISOR_CHUNK_TIMEOUT
     * forensic noise. Worker admission is bounded by expiring lease slots
     * plus the existing OkHttp dispatcher (maxRequestsPerHost=16 per
     * V5.9.1032), so we cannot permanently starve the next cycle.
     *
     * The returned SupervisorPhaseResult.processed is "spawned this tick",
     * not "completed this tick". For long-tail telemetry, audit
     * supervisorLifetimeProcessed / supervisorLifetimeSpawned counters.
     */
    private fun fireSupervisorWorkers(
        orderedMints: List<String>,
        cfg: com.lifecyclebot.data.BotConfig,
        wallet: com.lifecyclebot.network.SolanaWallet?,
        lastSuccessfulPollMs: Long,
        loopCount: Int,
    ): SupervisorPhaseResult {
        if (!status.running) return SupervisorPhaseResult(0, orderedMints.size, false)
        // V5.9.1073 — saturation is OBSERVATION ONLY.
        // The old pool reset path force-set supervisorActive=0 at cap, which
        // created phantom/negative accounting when late workers released. Do not
        // reset here. Clamp any historical negative value, log sustained full-cap
        // saturation, and let timed slot releases drain naturally.
        run {
            val now = System.currentTimeMillis()
            supervisorClampIfNegative("pre_cycle")
            val currentActive = supervisorLeases.size
            if (currentActive >= supervisorEffectiveCap()) {
                val stallMs = now - supervisorLastSpawnAt.get()
                if (stallMs >= SUPERVISOR_POOL_STALL_MS) {
                    supervisorLifetimeSaturationEvents.incrementAndGet()
                    supervisorLastSpawnAt.set(now)
                    try {
                        ForensicLogger.lifecycle(
                            "SUPERVISOR_POOL_SATURATED_NO_RESET",
                            "stallMs=$stallMs cap=$SUPERVISOR_MAX_INFLIGHT active=$currentActive events=${supervisorLifetimeSaturationEvents.get()}",
                        )
                    } catch (_: Throwable) {}
                }
            }
        }
        var spawned = 0
        var skipped = 0
        var cooldownSkipped = 0
        var shouldPollSkipped = 0
        try { markProgress("SUPERVISOR") } catch (_: Throwable) {}
        for (mint in orderedMints) {
            if (!status.running) break
            // V5.9.1180 — pre-admission filters. Do not acquire a lease or spawn
            // watchdog/IO coroutines for mints that are temporarily cooled after a
            // worker timeout, or that the orchestrator already says should not be
            // polled this tick. Open positions bypass timeout cooldown above.
            if (supervisorTimeoutCooldownActive(mint)) {
                skipped++
                cooldownSkipped++
                continue
            }
            if (orchestrator?.shouldPoll(mint) == false) {
                skipped++
                shouldPollSkipped++
                continue
            }
            val leaseId = supervisorTryAcquireSlot(mint)
            if (leaseId <= 0L) {
                skipped++
                continue
            }
            supervisorLifetimeSpawned.incrementAndGet()
            // V5.9.1042 — record last-successful-spawn timestamp so the
            // watchdog above can detect prolonged pool stalls.
            supervisorLastSpawnAt.set(System.currentTimeMillis())
            // V5.9.1046 — SLOT-RELEASE DECOUPLE. Operator V5.9.1045 dump
            // showed SUPERVISOR_WORKER_TIMEOUTs firing but slots still held; V5.9.1073 uses 5s
            // timeout working) but ~36 slots still held between resets.
            // Root cause: withTimeoutOrNull SUSPENDS the outer coroutine
            // until runInterruptible's inner block returns — and
            // processTokenCycle's outer try/catch SWALLOWS
            // InterruptedException ("Error [\$mint]" log), so the runaway
            // thread keeps running and the slot stays held until it
            // organically exits. Fix: spawn a separate watchdog coroutine
            // that delays for timeout+500ms then unconditionally releases
            // the slot via AtomicBoolean.compareAndSet. The main worker's
            // finally block also calls release(), but the CAS ensures
            // only one of them actually decrements. Bound: slot is now
            // guaranteed to free within timeout+0.5s regardless of whether
            // the inner thread ever returns.
            // V5.9.1415 — LEASE/WORKER ACCOUNTING FIX. The old watchdog released
            // the slot at SUPERVISOR_LEASE_TTL_MS (4750ms) — BEFORE the worker's
            // own 5000ms timeout could fire — while the worker coroutine kept
            // running. That freed the lease (active=leases.size shrank) while real
            // in-flight work exceeded the lease count, so new workers were admitted
            // over the real cap, IO saturated, workerTimeout climbed, and because
            // the timer (not the TTL prune) did the release, expiredLeases stayed 0:
            // the operator's exact "cap hit without lease expiry" signature.
            // FIX: hold a reference to the worker job; the safety-net watchdog now
            // fires AFTER the worker timeout + 750ms grace and CANCELS the job
