        } catch (e: Exception) {
            failCount++
            ErrorLogger.error("BotService", "ManipulatedTraderAI init FAILED: ${e.message}", e)
        }
        
        // V5.2.12: Quality Trader - professional mid-cap layer
        try {
            com.lifecyclebot.v3.scoring.QualityTraderAI.init(cfg.paperMode)
