                    ErrorLogger.crash("BotService",
                        "🚨 PROFIT-FLOOR REGRESSION AT BOOT: getDynamicFluidStop(peak=377%,now=251%) returned $testStop — MUST be positive and <= peak. Runners will not lock gains. This was the UGOR +290% → +50% bug.",
                        RuntimeException("profit-floor self-check failed: stop=$testStop"))
                } else {
                    ErrorLogger.info("BotService",
                        "✅ Profit-floor self-check: peak=377% now=251% → lock at +${testStop.toInt()}% (exit fires correctly)")
                }
            } catch (e: Exception) {
                ErrorLogger.warn("BotService", "Profit-floor self-check skipped: ${e.message}")
            }
            initCount++
        } catch (e: Exception) {
            failCount++
            ErrorLogger.error("BotService", "FluidLearningAI init FAILED: ${e.message}", e)
        }
        
        // Update FinalDecisionGate mode
        FinalDecisionGate.setModeForVeto(cfg.paperMode)
        
        // ═══════════════════════════════════════════════════════════════════════════
        // V4.0: Initialize GlobalTradeRegistry from config watchlist
        // ═══════════════════════════════════════════════════════════════════════════
        try {
            GlobalTradeRegistry.init(cfg.watchlist, "CONFIG")
            initCount++
        } catch (e: Exception) {
            failCount++
            ErrorLogger.error("BotService", "GlobalTradeRegistry init FAILED: ${e.message}", e)
        }
        
        // Set readiness flag - only if critical layers initialized
        // Critical: Treasury, ShitCoin, BlueChip, FluidLearning, GlobalTradeRegistry
        allTradingLayersReady = failCount == 0
        
        if (allTradingLayersReady) {
            addLog("✅ All $initCount trading layers initialized")
        } else {
            addLog("⚠️ Trading layers: $initCount OK, $failCount FAILED - trading may be limited")
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // PRICE FALLBACK HELPER - Extracted to reduce botLoop complexity
    // ═══════════════════════════════════════════════════════════════════════════
    
    /**
     * Try to get price data from fallback sources (Birdeye, pump.fun)
     * when Dexscreener doesn't have the pair.
     * Returns true if data was fetched successfully.
     */
    /**
     * V5.0.7176 — dispatch a protective exit the scheduler has already latched.
     *
     * Extracted because the risk-clock callback now reaches it from two places:
     * the tick where the latch is first made (fresh mark in hand) and any later
     * tick where the latch is still outstanding — including ticks where the
     * feed has since gone dark. Duplicating a sell dispatch to serve those two
     * callers would be exactly the kind of second copy that has bitten this
     * codebase repeatedly, so there is one.
     *
     * The caller owns the decision. This only executes it.
     */
    private fun expressVolumeSurge7293(ts: com.lifecyclebot.data.TokenState): Double {
        val bars = try { synchronized(ts) { ts.history.toList() } } catch (_: Throwable) { return 0.0 }
            .filter { it.volume24h.isFinite() && it.volume24h > 0.0 }
            .takeLast(13)
        if (bars.size < 7) return 0.0
        val prior = bars.dropLast(1)
        val mean = prior.sumOf { it.volume24h } / prior.size
        if (!mean.isFinite() || mean <= 0.0) return 0.0
        val r = bars.last().volume24h / mean
        try { PipelineHealthCollector.labelInc("EXPRESS_VOLUME_SURGE_MEASURED_7293") } catch (_: Throwable) {}
        return if (r.isFinite()) r.coerceIn(0.0, 50.0) else 0.0
    }

    private fun catastropheContradicted7289(ts: com.lifecyclebot.data.TokenState, markPx: Double): Boolean {
        if (!markPx.isFinite() || markPx <= 0.0) return false
        val src = ts.lastPriceSource.uppercase()
        if (src.contains("PUMP_CURVE_RPC") || src.contains("JUPITER_QUOTE")) return false
        val repaired = try {
            com.lifecyclebot.engine.truth.MarkIdentityRepairAuthority7236.getRepairedPriceIfFresh(ts.mint)
        } catch (_: Throwable) { null }
        val fanout = try {
            com.lifecyclebot.network.ParallelMarkFanout7088.resolve7088(listOf(ts.mint))[ts.mint]
        } catch (_: Throwable) { null }
        val fanoutPx = fanout?.takeIf { !(it.sourceCount >= 2 && !it.corroborated) }?.priceUsd
        fun above(other: Double?): Boolean =
            other != null && other.isFinite() && other > 0.0 && other / markPx >= 2.0
        val contradicted = above(repaired) || above(fanoutPx)
        try {
            PipelineHealthCollector.labelInc(
                if (contradicted) "PROTECTIVE_CATASTROPHE_REFUSED_CONTRADICTED_7289"
                else "PROTECTIVE_CATASTROPHE_UNCONTRADICTED_7289"
            )
            if (contradicted) ForensicLogger.lifecycle(
                "PROTECTIVE_CATASTROPHE_REFUSED_CONTRADICTED_7289",
                "mint=${ts.mint.take(10)} sym=${ts.symbol} mark=$markPx entry=${ts.position.entryPrice} " +
                    "src=${ts.lastPriceSource} repaired=${repaired ?: "none"} fanout=${fanoutPx ?: "none"} " +
                    "action=hold_latch_retry_on_redispatch",
            )
        } catch (_: Throwable) {}
        return contradicted
    }

    private fun dispatchProtectiveExit7176(
        ts: com.lifecyclebot.data.TokenState,
        positionId: String,
        mint: String,
        kind: com.lifecyclebot.engine.truth.ProtectiveExitScheduler6450.TriggerKind,
        markPx: Double,
        markAgeMs: Long,
        heldMs: Long,
        paperMode: Boolean,
        firstAttempt: Boolean,
    ) {
        try {
            PipelineHealthCollector.labelInc("RISK_CLOCK_PROTECTIVE_EXIT_ACTED_6882_$kind")
            ForensicLogger.lifecycle(
                "RISK_CLOCK_PROTECTIVE_EXIT_ACTED_6882",
                "positionId=${positionId.take(12)} mint=${mint.take(10)} kind=$kind " +
                    "mark=${"%.8f".format(markPx)} entry=${"%.8f".format(ts.position.entryPrice)} " +
                    "markAgeMs=$markAgeMs heldMs=$heldMs firstAttempt=$firstAttempt",
            )
        } catch (_: Throwable) {}
        // Execution is dispatched to IO, never run inline. CanonicalRiskClock6454
        // ticks on Dispatchers.Default (sized to CPU count) and requestSell is
        // synchronous network I/O on a live fill — BotService:5636 records what
        // happened the last time a burst of inline requestSell blocked its
        // scope: "cascade UI stalls". Blocking the risk clock would also delay
        // the very detection cadence this fix exists to guarantee.
        //
        // V5.0.7176 — fan-out is bounded by ProtectiveExitScheduler6450's
        // dispatch claim (one per position per REDISPATCH_INTERVAL_MS), not by
        // the old one-shot latch check, so a refused exit is retried instead of
        // being abandoned for the life of the process.
        val sellReason6882 = "PROTECTIVE_EXIT_${kind}_6450_RISKCLOCK"
        scope.launch(kotlinx.coroutines.Dispatchers.IO) {
            // V5.0.7289 §A CATASTROPHE THE MARKET CONTRADICTS IS NOT ONE.
            //
            // 5.0.7288: LinkhB (wrapped Chainlink, mcap $9.6B) closed from the
            // QUALITY lane at sol=0.000 pnl=-100% on this reason. The risk clock
            // checks a mark's age and nothing else, and TokenMetricsAuthority7069
            // counted 6,658 identity breaks in the same run (worst 17,967,607x):
            // a fresh wrong-pair price crossed entry*0.75, latched CATASTROPHE,
            // and the fill booked a total loss on a blue chip. The scan-path
            // catastrophe asks for evidence (6904) and the paper fill's own
            // contradiction check (7273) only covers the first ten minutes of a
            // hold, so a held position had neither.
            //
            // Before a CATASTROPHE sell leaves, the stack is asked once. Only an
            // independent price reading at least 2x ABOVE the triggering mark
            // refuses it; silence is not contradiction, so a token that really
            // died still closes. The latch is untouched and the 30 s redispatch
            // asks again, so a genuine collapse is delayed by one question, not
            // held. Stop-loss and every other kind pass through unchanged.
            if (kind == com.lifecyclebot.engine.truth.ProtectiveExitScheduler6450.TriggerKind.CATASTROPHE &&
                catastropheContradicted7289(ts, markPx)
            ) return@launch
            try {
                executor.requestSell(
                    ts = ts,
                    reason = sellReason6882,
                    wallet = WalletManager.getWallet(),
                    walletSol = status.getEffectiveBalance(paperMode),
                )
            } catch (t: Throwable) {
                try {
                    PipelineHealthCollector.labelInc("RISK_CLOCK_PROTECTIVE_EXIT_SELL_ERROR_6882")
                    ForensicLogger.lifecycle(
                        "RISK_CLOCK_PROTECTIVE_EXIT_SELL_ERROR_6882",
                        "mint=${mint.take(10)} reason=$sellReason6882 err=${t.message?.take(120)}",
                    )
                } catch (_: Throwable) {}
            }
        }
    }

    // V5.9.423 — broadcast a successfully-resolved fallback price to every
    // sub-trader that actually holds this mint. Previously tryFallbackPriceData
    // only updated ts.lastPrice, so sub-trader rows (esp. Quality) still
    // showed "— stale · no live feed 16m" because their per-position
    // lastSeenPrice / lastPriceUpdateMs never got touched even when Birdeye
    // or pump.fun had fresh data. Each updateLivePrice is a no-op for
    // traders that don't hold the mint, so it's safe to fan out blindly.
    //
    // V5.0.7175 §THE_THIRD_PLACE_THE_APP_WRITES_A_MARK.
    //
    // V5.0.6999 taught the Solana open-position tick loop to stamp
    // QuoteFreshnessGuard when it commits a mark, because the exit feed tests
    // PROVENANCE, not ts.lastPrice. V5.0.7010 found the same hole in the
    // cross-asset router and stamped that too, and its own comment says the
    // 6999 fix "covered one of the two places the app writes a mark."
    //
    // There were three. tryFallbackPriceData is the exit feed's OWN dedicated
    // Solana refresh — the coroutine canonicalExitTokenSnapshot6512 launches
    // for precisely the positions it just counted as unmarked — and all four
    // of its success branches write ts.lastPrice and stamp nothing.
    //
    // That closes a loop that can never open:
    //
    //   refreshNeeded6651 = ... || !provenanceFresh6651     -> true
    //     -> launch tryFallbackPriceData(mint, ts)
    //       -> a provider answers, ts.lastPrice is committed, returns true
    //         -> nothing is written to the guard the exit feed consults
    //           -> provenanceFresh6651 is still false on the next tick
    //             -> refreshNeeded6651 is true again, forever.
    //
    // The position is priced and the exit engine cannot see that it is priced,
    // so MissingMarkExitVeto6835 keeps deferring, StalePriceExitGuard keeps
    // returning refresh_hold_no_terminal, the basis stays in openCost and the
    // cash never comes back. Operator 5.0.7174: missingMark=33 of 72 open,
    // STALE_PRICE_EXIT_DEFERRED_6825=2081, cash 3.2096 against openCost 8.8572,
    // INSUFFICIENT_SOL=108, BELOW_MIN_NOTIONAL=98. Funded entries were being
    // refused for want of cash that unexitable inventory was sitting on.
    //
    // This is the ONE function all four commit branches already call, and every
    // caller is a live REST provider reply (Birdeye overview, the DexScreener
    // token-address endpoint, BirdeyeOracle, the pump.fun frontend) — verified
    // by grep, four call sites, no synthetic or derived price reaches here. So
    // the stamp belongs here, where a mark write and its provenance can no
    // longer be separated by a fifth branch someone adds later.
    //
    // `provenanceSource7175` is REQUIRED rather than defaulted for that exact
    // reason: a future caller must state where its number came from, and a
    // caller holding a DERIVED price must not reach this function at all.
    // Nothing about exit thresholds or protective logic changes here — this
    // only lets the exit engine see marks it is already being given.
    private fun broadcastFallbackPrice(mint: String, priceUsd: Double, provenanceSource7175: String) {
        if (priceUsd <= 0) return
        try {
            com.lifecyclebot.engine.truth.QuoteFreshnessGuard6452.note(
                mint = mint,
                priceUsd = priceUsd,
                source = com.lifecyclebot.engine.truth.QuoteFreshnessGuard6452.Provenance.REST_LIVE,
            )
            PipelineHealthCollector.labelInc("EXIT_FALLBACK_MARK_STAMPED_7175_$provenanceSource7175")
        } catch (_: Throwable) {}
        try { com.lifecyclebot.v3.scoring.QualityTraderAI.updateLivePrice(mint, priceUsd) } catch (_: Throwable) {}
        try { com.lifecyclebot.v3.scoring.BlueChipTraderAI.updateLivePrice(mint, priceUsd) } catch (_: Throwable) {}
        try { com.lifecyclebot.v3.scoring.ShitCoinTraderAI.updateLivePrice(mint, priceUsd) } catch (_: Throwable) {}
        try { com.lifecyclebot.v3.scoring.MoonshotTraderAI.updateLivePrice(mint, priceUsd) } catch (_: Throwable) {}
        // CashGenerationAI / ManipulatedTraderAI / ShitCoinExpress don't
        // expose updateLivePrice — they derive lastSeenPrice inside checkExit.
    }

    // V5.9.426 — EXIT SAFETY NET helper.
    // V5.9.427 — extended from a simple -20% hard-floor-only check to a full
    // delegation to each meme sub-trader's canonical checkExit() with the
    // freshly-refreshed fallback price. This means trail exits, profit-floor
    // locks, partial-take rungs, rug detection AND the hard-floor SL all fire
    // on cycles where the primary DexScreener feed is down and
    // processTokenCycle would otherwise return early. Covers ShitCoinTraderAI
    // and MoonshotTraderAI (the meme lanes). A final hard-floor fallback runs
    // if neither sub-trader has the position registered (orphaned ts.position).
    /**
     * V5.9.678 — Universal SL safety-net sweep.
     *
     * Runs once per botLoop tick across ALL open positions, invoking
     * runFallbackSafetyExit() for each. The delegate function is already
     * idempotent (tries lane checkExit if the token is registered with
     * ShitCoinTraderAI/MoonshotTraderAI, falls back to a -20% hard floor
     * for orphans whose tradingMode tag is null/empty). The sweep exists
     * specifically to rescue positions that the lane-specific exit branches
     * in processTokenCycle (which both require a populated tradingMode
     * field) silently skip — operator screenshot in V5.9.677 showed five
     * paper positions sitting 50-80 percentage points past the configured
     * -20% SL because of this gap.
     *
     * Kept as a separate top-level method (not inlined into botLoop) so
     * the bytecode lives in its own slot and never threatens botLoop's
     * JVM 64KB method-size budget. Returns immediately if the bot is
     * not running.
     */
    /**
     * V5.0.6402 §C — SWEEP HARD DEADLINE.
     *
     * The 6401 snapshot showed max bot cycles of 66-99 seconds. Root
     * cause: this loop ran a per-position provider-I/O call
     * (`runFallbackSafetyExit` → `executor.getActualPricePublic`)
     * synchronously over ALL open positions. With 97 positions in
     * the registry and providers degraded (Birdeye 401, Helius 429,
     * DexScreener 5xx), each eval could burn 15-20s on network
     * timeouts and the whole sweep suspended the bot loop.
     *
     * Directive: "individual exit evaluation: 250 ms" (per-pos
     * deadline enforced by short-circuiting to the next position if
     * the previous one overran) and "entire Universal SL sweep:
     * 3000 ms, hard emergency sweep deadline: 5000 ms".
     *
     * This wall-clock guard applies the sweep budget: after each
     * position, if elapsed >= HARD_DEADLINE_MS we DEFER the
     * remainder and continue on the next cycle. No position ever
     * suspends the bot loop past the deadline.
     */
    /** V5.0.7271 — mints whose universal-SL evaluation is dispatched and not yet returned. */
    private val universalSlInFlight7271: MutableSet<String> = java.util.concurrent.ConcurrentHashMap.newKeySet()

    private fun runUniversalSlSafetyNetSweep(cfg: BotConfig, wallet: SolanaWallet?) {
        if (!status.running) return
        val HARD_DEADLINE_MS = 5_000L
        val SOFT_DEADLINE_MS = 3_000L
        val PER_POSITION_ELAPSED_WARN_MS = 250L
        val sweepStartedAt = System.currentTimeMillis()
        var positionsSeen = 0
        var positionsEvaluated = 0
        var positionsDeferred = 0
        try {
            // Snapshot the token map so we never iterate while it mutates
            // under us (executor.requestSell sets isOpen=false in place).
            val openSnapshot = canonicalExitTokenSnapshot6512()
            positionsSeen = openSnapshot.size

            if (openSnapshot.isEmpty()) return

            for (ts in openSnapshot) {
                val elapsed = System.currentTimeMillis() - sweepStartedAt
                // V5.0.6402 §C — hard sweep deadline. Beyond this, defer
                // all remaining positions to the next tick.
                if (elapsed >= HARD_DEADLINE_MS) {
                    val remaining = openSnapshot.size - positionsEvaluated
                    positionsDeferred += remaining
                    try {
                        PipelineHealthCollector.labelInc("UNIVERSAL_SL_SWEEP_HARD_DEADLINE_6402")
                        ForensicLogger.lifecycle(
                            "UNIVERSAL_SL_SWEEP_HARD_DEADLINE_6402",
                            "elapsedMs=$elapsed positionsSeen=$positionsSeen positionsEvaluated=$positionsEvaluated deferred=$remaining budgetMs=$HARD_DEADLINE_MS",
                        )
                    } catch (_: Throwable) {}
                    break
                }
                val posStart = System.currentTimeMillis()
                // V5.0.7271 §THE_SWEEP_HELD_THE_LOOP_FOR_328_SECONDS.
                //
                // 5.0.7270: exit sweeps 9 started / 8 done, one still running at
                // lastEndedAgoMs=328665, six EXIT_COORDINATOR_STALE_RESET, 21
                // relaunch backoffs — while the hot tick's own gap gauge (7270)
                // read maxGap 5.7 s and fan-out max 3.0 s. The stall was not the
                // pricing; it was this loop calling runFallbackSafetyExit inline,
                // which calls executor.requestSell inline, on the bot loop
                // thread. The 6402 deadline is checked BETWEEN positions, so one
                // sell that waits on a lock or a provider holds every position
                // behind it and the loop that owns the heartbeat.
                //
                // Each evaluation is dispatched to the elastic IO pool with a
                // per-mint in-flight guard, so a slow sell delays only its own
                // mint and never the sweep, the heartbeat, or the next sweep.
                // The per-position timing is measured inside the dispatched
                // work so UNIVERSAL_SL_POSITION_SLOW_6402 still names the slow
                // mint. paperSell's own CAS door remains the duplicate guard.
                val mintKey7271 = ts.mint
                if (!universalSlInFlight7271.add(mintKey7271)) {
                    try { PipelineHealthCollector.labelInc("UNIVERSAL_SL_EVAL_SKIPPED_INFLIGHT_7271") } catch (_: Throwable) {}
                } else {
                    scope.launch(Dispatchers.IO) {
                        try {
                            runFallbackSafetyExit(ts, cfg, wallet)
                        } catch (e: Throwable) {
                            ErrorLogger.debug(
                                "BotService",
                                "universal SL sweep err ${ts.symbol}: ${e.message}"
                            )
                        } finally {
                            universalSlInFlight7271.remove(mintKey7271)
                            val posElapsed = System.currentTimeMillis() - posStart
                            if (posElapsed >= PER_POSITION_ELAPSED_WARN_MS) {
                                try {
                                    com.lifecyclebot.engine.truth.ExitSweepTiming7264.onSlowPosition(posElapsed)
                                    PipelineHealthCollector.labelInc("UNIVERSAL_SL_POSITION_SLOW_6402")
                                    ForensicLogger.lifecycle(
                                        "UNIVERSAL_SL_POSITION_SLOW_6402",
                                        "mint=${ts.mint.take(10)} sym=${ts.symbol} posElapsedMs=$posElapsed dispatched=true",
                                    )
                                } catch (_: Throwable) {}
                            }
                        }
                    }
                }
                positionsEvaluated++
                // Soft deadline advisory — sweep is still running but is
                // now over budget. Continue but log so the operator sees
                // the boundary event.
                if (elapsed in SOFT_DEADLINE_MS until HARD_DEADLINE_MS &&
                    positionsEvaluated == positionsSeen / 2) {
                    try { PipelineHealthCollector.labelInc("UNIVERSAL_SL_SWEEP_SOFT_DEADLINE_6402") } catch (_: Throwable) {}
                }
            }
        } catch (e: Throwable) {
            ErrorLogger.warn("BotService", "universal SL sweep top-level: ${e.message}")
        } finally {
            val total = System.currentTimeMillis() - sweepStartedAt
            // V5.0.7264 — the duration reaches the report, not only the forensic log.
            try { com.lifecyclebot.engine.truth.ExitSweepTiming7264.onSweep(total, positionsSeen, positionsEvaluated, positionsDeferred) } catch (_: Throwable) {}
            try {
                ForensicLogger.lifecycle(
                    "UNIVERSAL_SL_SWEEP_SUMMARY_6402",
                    "elapsedMs=$total positionsSeen=$positionsSeen positionsEvaluated=$positionsEvaluated positionsDeferred=$positionsDeferred hardDeadlineMs=$HARD_DEADLINE_MS",
                )
            } catch (_: Throwable) {}
        }
    }

    private fun runFallbackSafetyExit(ts: TokenState, cfg: BotConfig, wallet: SolanaWallet?) {
        try {
            val price = try { executor.getActualPricePublic(ts) } catch (_: Throwable) { ts.lastPrice }
            if (price <= 0.0 || ts.position.entryPrice <= 0.0) return
            val effectiveBalance = status.getEffectiveBalance(cfg.paperMode)

            // V5.9.678 — emit PHASE.EXIT forensic so the funnel counter
            // EXIT in the Pipeline Health dump finally reflects reality.
            // Prior to this, no code path anywhere in the bot emitted
            // PHASE.EXIT so operator dumps perpetually showed EXIT=0
            // even when many positions were being evaluated for exit.
            val _pnlVerdict6038 = OpenPnlSanity.inspectPosition(ts.position, price, "BotService.fallback_exit_phase_6038/${ts.symbol}/${ts.mint.take(8)}", emit = true)
            val _pnl = if (_pnlVerdict6038.ok) _pnlVerdict6038.pnlPct else 0.0
            try {
                ForensicLogger.phase(
                    ForensicLogger.PHASE.EXIT_GATE,
                    ts.symbol,
                    "pnl=${_pnl.toInt()}% mode=${ts.position.tradingMode.takeIf { it.isNotBlank() } ?: "NONE"} sc=${com.lifecyclebot.v3.scoring.ShitCoinTraderAI.hasPosition(ts.mint)} ms=${com.lifecyclebot.v3.scoring.MoonshotTraderAI.hasPosition(ts.mint)}"
                )
            } catch (_: Throwable) {}

            // ── ShitCoinTraderAI delegation ─────────────────────────────
            if (com.lifecyclebot.v3.scoring.ShitCoinTraderAI.hasPosition(ts.mint)) {
                val sig = com.lifecyclebot.v3.scoring.ShitCoinTraderAI.checkExit(ts.mint, price)
                if (sig != com.lifecyclebot.v3.scoring.ShitCoinTraderAI.ExitSignal.HOLD) {
                    ErrorLogger.warn("BotService",
                        "🛡️ [FALLBACK_EXIT][SHITCOIN] ${ts.symbol} | signal=$sig | price=$price (DexScreener down)")
                    if (sig == com.lifecyclebot.v3.scoring.ShitCoinTraderAI.ExitSignal.PARTIAL_TAKE) {
                        val partialReceipt6566 = executor.requestPartialSellConfirmed6566(
                            ts = ts, sellPercentage = 0.25,
                            reason = "FALLBACK_SHITCOIN_PARTIAL_TAKE",
                            wallet = wallet, walletBalance = effectiveBalance,
                        )
                        if (!partialReceipt6566.applied) { try { PipelineHealthCollector.labelInc("MEME_PARTIAL_NOT_APPLIED_6566_FALLBACK_SHITCOIN") } catch (_: Throwable) {}; return }
                        com.lifecyclebot.v3.scoring.ShitCoinTraderAI.markFirstTakeDone(ts.mint)
                        com.lifecyclebot.v3.scoring.ShitCoinTraderAI.onPartialSell(ts.mint, 0.25) // V5.9.705
                        com.lifecyclebot.engine.PositionPersistence.savePosition(ts)               // V5.9.705
                    } else {
                        val fbScResult = executor.requestSell(
                            ts = ts,
                            reason = "FALLBACK_SHITCOIN_${sig.name}",
                            wallet = wallet, walletSol = effectiveBalance,
                        )
                        // V5.9.706 FIX: clean up sub-trader state unless retryable
                        if (fbScResult != Executor.SellResult.FAILED_RETRYABLE) {
                            com.lifecyclebot.v3.scoring.ShitCoinTraderAI.closePosition(ts.mint, price, sig)
                            com.lifecyclebot.v3.V3EngineManager.onPositionClosed(ts.mint)
                        }
                    }
                    return
                }
            }

            // ── MoonshotTraderAI delegation ─────────────────────────────
            if (com.lifecyclebot.v3.scoring.MoonshotTraderAI.hasPosition(ts.mint)) {
                val sig = com.lifecyclebot.v3.scoring.MoonshotTraderAI.checkExit(ts.mint, price)
                if (sig != com.lifecyclebot.v3.scoring.MoonshotTraderAI.ExitSignal.HOLD) {
                    ErrorLogger.warn("BotService",
                        "🛡️ [FALLBACK_EXIT][MOONSHOT] ${ts.symbol} | signal=$sig | price=$price (DexScreener down)")
                    if (sig == com.lifecyclebot.v3.scoring.MoonshotTraderAI.ExitSignal.PARTIAL_TAKE) {
                        val partialPct = com.lifecyclebot.v3.scoring.MoonshotTraderAI.getPartialSellPct(ts.mint)
                        val partialReceipt6566 = executor.requestPartialSellConfirmed6566(
                            ts = ts, sellPercentage = partialPct,
                            reason = "FALLBACK_MOONSHOT_PARTIAL_TAKE_${(partialPct * 100).toInt()}PCT",
                            wallet = wallet, walletBalance = effectiveBalance,
                        )
                        if (!partialReceipt6566.applied) { try { PipelineHealthCollector.labelInc("MEME_PARTIAL_NOT_APPLIED_6566_FALLBACK_MOONSHOT") } catch (_: Throwable) {}; return }
                        com.lifecyclebot.v3.scoring.MoonshotTraderAI.onPartialSell(ts.mint, partialPct) // V5.9.705
                        com.lifecyclebot.engine.PositionPersistence.savePosition(ts)                    // V5.9.705
                    } else {
                        val fbMsResult = executor.requestSell(
                            ts = ts,
                            reason = "FALLBACK_MOONSHOT_${sig.name}",
                            wallet = wallet, walletSol = effectiveBalance,
                        )
                        // V5.9.706 FIX: clean up sub-trader state unless retryable
                        if (fbMsResult != Executor.SellResult.FAILED_RETRYABLE) {
                            com.lifecyclebot.v3.scoring.MoonshotTraderAI.closePosition(ts.mint, price, sig)
                            com.lifecyclebot.v3.V3EngineManager.onPositionClosed(ts.mint)
                        }
                    }
                    return
                }
            }

            // ── Last-resort hard-floor (orphaned position) ──────────────
            // If neither sub-trader has this mint registered (e.g. state
            // wasn't rehydrated after restart), still fire the canonical
            // -20% meme hard-floor to stop catastrophic bleed.
            val pnlVerdict6038 = OpenPnlSanity.inspectPosition(ts.position, price, "BotService.fallback_hard_floor_6038/${ts.symbol}/${ts.mint.take(8)}", emit = true)
            if (!pnlVerdict6038.ok) return
            val pnlPct = pnlVerdict6038.pnlPct
            if (pnlPct <= -20.0) {
                val nowMs = System.currentTimeMillis()
                val ageMs = (nowMs - ts.position.entryTime).coerceAtLeast(0L)
                val isPaper = ts.position.isPaperPosition
                val hasCanonicalLaneTag = ts.position.tradingMode.isNotBlank() &&
                    ts.position.tradingMode.uppercase() != "STANDARD"
                val hasPersisted = try {
                    com.lifecyclebot.engine.PositionPersistence.hasPersistedPosition(ts.mint)
                } catch (_: Throwable) { false }
                val sourceChangedUnrebased = isPaper &&
                    ts.position.entryPriceSource.isNotBlank() &&
                    ts.position.entryPriceSource != "UNKNOWN" &&
                    ts.lastPriceSource.isNotBlank() &&
                    ts.position.entryPriceSource != ts.lastPriceSource &&
                    !ts.position.priceBasisRescaled

                // V5.9.1109 — ghost-position containment.
                // The fallback orphan hard-floor is a LAST-resort safety net for
                // old/restored positions with no lane owner. It must not fire on
                // brand-new PAPER buys that have just been journaled/persisted but
                // have not yet been re-adopted by sub-trader active maps. The 1108
                // report showed 7 fresh paper positions force-sold in 1-7s with
                // fake -24%..-87% PnL. Those were accounting/price-basis ghosts,
                // not real market losses. Normal lane exits still enforce the
                // unconditional -15% stop; this guard only suppresses the orphan
                // fallback path until the position is old enough to be truly orphaned.
                if (isPaper && ageMs < 60_000L) {
                    try {
                        ForensicLogger.lifecycle(
                            "ORPHAN_FALLBACK_SUPPRESSED_FRESH_PAPER",
                            "symbol=${ts.symbol} mint=${ts.mint.take(10)} pnl=${pnlPct.toInt()} ageMs=$ageMs persisted=$hasPersisted mode=${ts.position.tradingMode} src=${ts.position.entryPriceSource}->${ts.lastPriceSource}"
                        )
                    } catch (_: Throwable) {}
                    return
                }
                if (isPaper && hasCanonicalLaneTag && hasPersisted && ageMs < 5 * 60_000L) {
                    try {
                        ForensicLogger.lifecycle(
                            "ORPHAN_FALLBACK_SUPPRESSED_CANONICAL_PAPER",
                            "symbol=${ts.symbol} mint=${ts.mint.take(10)} pnl=${pnlPct.toInt()} ageMs=$ageMs mode=${ts.position.tradingMode} persisted=true"
                        )
                    } catch (_: Throwable) {}
                    return
                }
                if (sourceChangedUnrebased) {
                    try {
                        ForensicLogger.lifecycle(
                            "ORPHAN_FALLBACK_SUPPRESSED_PRICE_BASIS",
                            "symbol=${ts.symbol} mint=${ts.mint.take(10)} pnl=${pnlPct.toInt()} ageMs=$ageMs src=${ts.position.entryPriceSource}->${ts.lastPriceSource}"
                        )
                    } catch (_: Throwable) {}
                    return
                }

                ErrorLogger.warn("BotService",
                    "🛑 [FALLBACK_SAFETY_SL][ORPHAN] ${ts.symbol} | ${pnlPct.toInt()}% — no sub-trader has mint; firing hard-floor")
                executor.requestSell(
                    ts = ts,
                    reason = "FALLBACK_ORPHAN_HARD_FLOOR_${pnlPct.toInt()}PCT",
                    wallet = wallet, walletSol = effectiveBalance,
                )
            }
        } catch (e: Exception) {
            ErrorLogger.debug("BotService", "[FALLBACK_SAFETY] error: ${e.message}")
        }
    }

    /**
     * V5.9.615 — Build a synthetic PairInfo from already-populated TokenState
     * fallback data (pump.fun API / Birdeye delivered price+mcap+liquidity into
     * ts.lastPrice / ts.lastMcap / ts.lastLiquidityUsd, but DexScreener has no
     * pair). This lets processTokenCycle continue into V3/ShitCoin entry
     * evaluation instead of returning early. Pre-graduation pump.fun tokens
     * are the ShitCoin lane's designed target market.
     *
     * Field semantics:
     *  - candle: synthetic 1-tick candle at current fallback price+mcap.
     *    Volume / buys / sells default to 0 — downstream scorers already
     *    handle "no data yet" via FluidLearningAI bootstrap heuristics.
     *  - liquidity / fdv: copied from ts. For pump.fun bonding-curve tokens
     *    this is mcap * 0.85 (set by tryFallbackPriceData seed path).
     *  - url: tagged so downstream source-detection sees pump.fun, which
     *    correctly routes the token into ShitCoinTraderAI.LaunchPlatform.PUMP_FUN.
     */
    private fun synthesizeFallbackPair(ts: com.lifecyclebot.data.TokenState): com.lifecyclebot.network.PairInfo? {
        if (ts.lastPrice <= 0.0) return null
        val nowMs = System.currentTimeMillis()
        val candle = com.lifecyclebot.data.Candle(
            ts = nowMs,
            priceUsd = ts.lastPrice,
            marketCap = ts.lastMcap.coerceAtLeast(0.0),
            volumeH1 = 0.0,
            volume24h = 0.0,
            buysH1 = 0,
            sellsH1 = 0,
            highUsd = ts.lastPrice,
            lowUsd = ts.lastPrice,
            openUsd = ts.lastPrice,
        )
        // URL hint so processTokenCycle's source-inference still tags pump.fun
        // correctly when ts.source is empty (the WS feed sets PUMP_PORTAL_WS,
        // but defense-in-depth: anything else lands here too).
        val url = if (ts.source.contains("PUMP", ignoreCase = true)) {
            "https://pump.fun/${ts.mint}"
        } else {
            ""
        }
        return com.lifecyclebot.network.PairInfo(
            pairAddress = "",                              // no on-chain pair yet (bonding curve)
            baseSymbol = ts.symbol.ifBlank { ts.mint.take(6) },
            baseName = ts.name.ifBlank { ts.symbol.ifBlank { ts.mint.take(6) } },
            url = url,
            candle = candle,
            pairCreatedAtMs = ts.addedToWatchlistAt.takeIf { it > 0 } ?: nowMs,
            liquidity = ts.lastLiquidityUsd.coerceAtLeast(0.0),
            fdv = ts.lastFdv.takeIf { it > 0 } ?: ts.lastMcap.coerceAtLeast(0.0),
            baseTokenAddress = ts.mint,
        )
    }

    // V5.0.7225 §THE_TOP_UP_REACHED_A_DEAD_PROVIDER_AND_THREE_LOCKED_DOORS.
    //
    // Operator 5.0.7219 (paper): RISK_CLOCK_BLOCKED_7001_MARK_STALE=7135 of
    // posEvals=10125 — seventy percent of every protective-exit evaluation
    // fell into the heartbeat-only branch — against MARK_REFRESH_TTL_SKIPPED_6594
    // =14044. 7204 moved the refresh TRIGGER to 30s and its own comment says
    // why: "a mark is never topped up while it is still good". It did not
    // look inside the function the trigger launches.
    //
    // Inside, the cascade is: Birdeye overview, then DexScreener token-address,
    // then BirdeyeOracle, then pump.fun — and the last three are each gated on
    // `age > 120_000L`. The Birdeye key on this device is 401-dead
    // (`birdeye sr=0% http=401`, every snapshot since 6947). So a top-up fired
    // at 30s asked one dead provider and walked past three locked doors,
    // advanced nothing, and returned false. The exit-feed caller then judged
    // success by `ts.lastPrice > 0.0` — a positive STALE mark — stamped
    // exitMarkRefreshLastSuccessMs6594, and re-armed the 30s TTL. Each
    // position therefore cycles: usable 0-60s, MARK_STALE 60-120s, and only
    // at 120s does a door open. That is >= 50% stale by construction, and
    // 70% once TTL phase and round trips are added. 7204 half-fixed it: same
    // defect shape (a remedy behind a threshold reachable only after the
    // harm), one screen further down.
    //
    // `secondaryStaleAfterMs7225` replaces the three literal 120_000L gates.
    // It DEFAULTS to 120_000L so requestEntryHydration6647 — the only other
    // caller — is byte-for-byte unchanged. The exit-feed caller passes
    // MarkRefreshDedupTtl6594.TTL_SUCCESS_MS, the same 30s the trigger and
    // the storm guard already share, so the doors open exactly when the
    // top-up knocks. Traffic stays bounded by that TTL: <=1 refresh attempt
    // per mint per 30s on success, 5s backoff on failure, as 6594 designed.
    private fun tryFallbackPriceData(
        mint: String,
        ts: TokenState,
        secondaryStaleAfterMs7225: Long = 120_000L,
    ): Boolean {
        // Try Birdeye first
        try {
            val cfg2 = ConfigStore.load(applicationContext)
            val ov = com.lifecyclebot.network.BirdeyeApi(cfg2.birdeyeApiKey).getTokenOverview(mint)
            if (ov != null && ov.priceUsd > 0) {
                synchronized(ts) {
                    ts.lastPrice = ov.priceUsd
                    ts.lastPriceUpdate = System.currentTimeMillis()
                    ts.lastPriceSource = "BIRDEYE_OVERVIEW"  // V5.9.744
                    ts.lastLiquidityUsd = ov.liquidity
                    ts.lastMcap = ov.marketCap
                    ts.lastFdv = ov.marketCap
                    val syntheticCandle = com.lifecyclebot.data.Candle(
                        ts = System.currentTimeMillis(), priceUsd = ov.priceUsd,
                        marketCap = ov.marketCap, volumeH1 = 0.0, volume24h = 0.0,
                        buysH1 = 0, sellsH1 = 0, highUsd = ov.priceUsd,
                        lowUsd = ov.priceUsd, openUsd = ov.priceUsd,
                    )
                    synchronized(ts.history) {
                        ts.history.addLast(syntheticCandle)
                        if (ts.history.size > 300) ts.history.removeFirst()
                    }
                }
                broadcastFallbackPrice(mint, ov.priceUsd, "BIRDEYE_OVERVIEW")   // V5.9.423, V5.0.7175
                addLog("📡 Birdeye: ${ts.symbol} \$${ov.priceUsd}", mint)
                return true
            }
        } catch (_: Exception) {}

        // V5.9.423 — DexScreenerOracle (separate code path from dex.getBestPair,
        // different endpoint, different cache). When the pair-based call fails
        // this token-address call often still returns — DexScreener caches
        // token-level and pair-level data independently.
        if (ts.lastPrice <= 0 || (System.currentTimeMillis() - ts.lastPriceUpdate) > secondaryStaleAfterMs7225) {
            try {
                val priceUsd = kotlinx.coroutines.runBlocking {
                    kotlinx.coroutines.withTimeoutOrNull(2000L) {
                        com.lifecyclebot.perps.DexScreenerOracle.getPriceByAddress(mint)
                    }
                }
                if (priceUsd != null && priceUsd > 0) {
                    synchronized(ts) {
                        ts.lastPrice = priceUsd
                        ts.lastPriceUpdate = System.currentTimeMillis()
                        ts.lastPriceSource = "PAIR_FALLBACK"  // V5.9.744
                    }
                    broadcastFallbackPrice(mint, priceUsd, "DEXSCREENER_TOKEN")   // V5.0.7175
                    addLog("📊 DexScreener(token): ${ts.symbol} \$${priceUsd}", mint)
                    return true
                }
            } catch (_: Throwable) {}
        }

        // V5.9.423 — BirdeyeOracle token-address API (different from BirdeyeApi
        // used above, which is overview-focused; this one is price-focused and
        // hits a separate rate-limit bucket).
        if (ts.lastPrice <= 0 || (System.currentTimeMillis() - ts.lastPriceUpdate) > secondaryStaleAfterMs7225) {
            try {
                val priceUsd = kotlinx.coroutines.runBlocking {
                    kotlinx.coroutines.withTimeoutOrNull(2000L) {
                        com.lifecyclebot.perps.BirdeyeOracle.getPriceByAddress(mint)
                    }
                }
                if (priceUsd != null && priceUsd > 0) {
                    synchronized(ts) {
                        ts.lastPrice = priceUsd
                        ts.lastPriceUpdate = System.currentTimeMillis()
                        ts.lastPriceSource = "PAIR_FALLBACK"  // V5.9.744
                    }
                    broadcastFallbackPrice(mint, priceUsd, "BIRDEYE_ORACLE")   // V5.0.7175
                    addLog("🐦 BirdeyeOracle: ${ts.symbol} \$${priceUsd}", mint)
                    return true
                }
            } catch (_: Throwable) {}
        }

        // Try pump.fun API
        // V5.9.423 — also retry pump.fun if the last successful price is >120s
        // stale. Previously the `if (ts.lastPrice <= 0)` guard meant pump.fun
        // was only consulted on brand-new holds that had never been priced.
        // V5.0.7100 §ASK_PUMPFUN_ONLY_ABOUT_PUMPFUN_MINTS. The device reports
        // pumpfun sr=17% 4xx=306 5xx=485. frontend-api-v3/coins/<mint> can only
        // answer for a pump.fun mint; for anything else a 404 is the correct and
        // inevitable reply, and we were spending the host's budget — and its
        // circuit-breaker headroom — asking questions with a known answer.
        // V5.0.7089 already established the predicate for the supply seed; this
        // is the same fact and must use the same authority, not a second one.
        val pumpFunMint7100 = try {
            com.lifecyclebot.network.PumpFunDirectApi.isPumpFunMint(mint)
        } catch (_: Throwable) { false }
        if (!pumpFunMint7100) {
            try { PipelineHealthCollector.labelInc("PUMPFUN_PRICE_SKIPPED_NOT_PUMPFUN_MINT_7100") } catch (_: Throwable) {}
        }
        if (pumpFunMint7100 &&
            (ts.lastPrice <= 0 || (System.currentTimeMillis() - ts.lastPriceUpdate) > secondaryStaleAfterMs7225)) {
            try {
                val client = com.lifecyclebot.network.SharedHttpClient.builder()
                    .connectTimeout(5, java.util.concurrent.TimeUnit.SECONDS)
                    .readTimeout(5, java.util.concurrent.TimeUnit.SECONDS).build()
                val request = okhttp3.Request.Builder()
                    .url("https://frontend-api-v3.pump.fun/coins/$mint")
                    .header("Accept", "application/json").build()
                // V5.0.7100 — this site called client.newCall(request).execute()
                // directly. It recorded the outcome to ApiHealthMonitor, which is
                // why the health table showed the 5xx storm, but it never asked
                // ApiBackoff whether the host was locked out — so while pumpfun
                // sat at 17% and the circuit was armed, this caller kept firing.
                // The same violation the Golden Tape already forbids for
                // DexScreener ("never bypass HealthAwareHttp/ApiBackoff with a
                // raw retry"). HealthAwareHttp also owns the AutoEndpointMigrator
                // rewrite and the health/backoff recording, so the duplicated
                // copies of both are gone with it.
                val response = com.lifecyclebot.engine.HealthAwareHttp.execute(
                    client, request, host = "pumpfun",
                )
                if (response.isSuccessful) {
                    val body = response.body?.string()
                    if (body != null) {
                        val json = org.json.JSONObject(body)
                        val mcap = json.optDouble("usd_market_cap", 0.0)
                        // NOTE: pump.fun API's "price" field is in SOL (not USD), so we
                        // compute a correct USD price from usd_market_cap / total_supply.
                        //
                        // V5.0.7017 — the divisor was wrong by exactly 10^decimals.
                        // `total_supply` is in RAW BASE UNITS (1e15 for the standard
                        // 1e9-token mint), and the old line divided by it as though it
                        // were whole tokens, so every pump.fun mark came out a
                        // millionfold too small. That is what produced the operator's
                        // 5.0.7012 cross-basis refusals and, through them, the frozen
                        // marks and the 100-position hard cap. See PumpFunPriceUnits7017
                        // for the arithmetic straight off that snapshot.
                        val priceUsd = com.lifecyclebot.engine.PumpFunPriceUnits7017.priceUsd(json)
                        if (mcap > 0) {
                            synchronized(ts) {
                                ts.lastPrice = priceUsd
                                ts.lastPriceUpdate = System.currentTimeMillis()
                                ts.lastPriceSource = "PUMP_FUN_FRONTEND_API"  // V5.9.744
                                ts.lastPriceDex = "PUMP_FUN"
                                ts.lastMcap = mcap
                                ts.lastFdv = mcap
                                ts.lastLiquidityUsd = mcap * 0.1
                                val syntheticCandle = com.lifecyclebot.data.Candle(
                                    ts = System.currentTimeMillis(), priceUsd = priceUsd,
                                    marketCap = mcap, volumeH1 = 0.0, volume24h = 0.0,
                                    buysH1 = 0, sellsH1 = 0, highUsd = priceUsd,
                                    lowUsd = priceUsd, openUsd = priceUsd,
                                )
                                synchronized(ts.history) {
                                    ts.history.addLast(syntheticCandle)
                                    if (ts.history.size > 300) ts.history.removeFirst()
                                }
                            }
                            addLog("🎯 Pump.fun: ${ts.symbol} mcap=\$${mcap.toInt()} priceUsd=\$${String.format("%.10f", priceUsd)}", mint)
                            broadcastFallbackPrice(mint, priceUsd, "PUMPFUN_FRONTEND")   // V5.9.423, V5.0.7175
                            return true
                        }
                    }
                }
            } catch (_: Exception) {}
        }
        return false
    }

    private val entryHydrationPending6647 = java.util.concurrent.ConcurrentHashMap.newKeySet<String>()
    /** V5.0.7273 — last fan-out hydration per mint; one eight-feed pass per 30 s is plenty. */
    private val entryHydrationFanoutLastMs7273 = java.util.concurrent.ConcurrentHashMap<String, Long>()

    private fun requestEntryHydration6647(mint: String, ts: TokenState) {
        if (!entryHydrationPending6647.add(mint)) return
        scope.launch(supervisorDispatcher6647 + CoroutineName("entry-hydration-${mint.take(8)}")) {
            try {
                // V5.0.7273 §CANDIDATES_NEVER_REACHED_THE_FAN_OUT.
                //
                // The eight-feed fan-out priced held positions only. A candidate
                // whose DexScreener poll was rate-limited (5.0.7272: 3,312 cycles
                // on a synthesized pair) or that 7270 deliberately left unpriced
                // ("leave to fan-out", 18 majors this session) had only this
                // serial cascade — Birdeye 401-dead, DexScreener behind the same
                // limiter, pump.fun at 26% — and so BLUECHIP raised 101 intents
                // with 0 marks, CORE 260 with 0. Ask the stack first, once per
                // 30 s per mint; a single unambiguous feed or an agreeing set is
                // written as a dated live price under its real label, a
                // contested pass is not written (see the hot loop), and the
                // cascade still runs for liquidity and pool metadata.
                val nowFan7273 = System.currentTimeMillis()
                val lastFan7273 = entryHydrationFanoutLastMs7273[mint] ?: 0L
                if (nowFan7273 - lastFan7273 >= 30_000L) {
                    entryHydrationFanoutLastMs7273[mint] = nowFan7273
                    val fan7273 = try {
                        com.lifecyclebot.network.ParallelMarkFanout7088.resolve7088(listOf(mint))[mint]
                    } catch (_: Throwable) { null }
                    val usable7273 = fan7273 != null && fan7273.priceUsd.isFinite() && fan7273.priceUsd > 0.0 &&
                        !(fan7273.sourceCount >= 2 && !fan7273.corroborated)
                    if (usable7273 && fan7273 != null) {
                        val label7273 = if (fan7273.corroborated) "FANOUT_CORROBORATED_7088_x${fan7273.agreeingCount}" else "FANOUT_UNCORROBORATED_7088"
                        synchronized(ts) {
                            ts.lastPrice = fan7273.priceUsd
                            ts.lastPriceUpdate = System.currentTimeMillis()
                            ts.lastPriceSource = label7273
                        }
                        try {
                            com.lifecyclebot.engine.truth.QuoteFreshnessGuard6452.note(
                                mint = mint, priceUsd = fan7273.priceUsd,
                                source = com.lifecyclebot.engine.truth.QuoteFreshnessGuard6452.Provenance.REST_LIVE,
                                sourceCount7188 = fan7273.sourceCount, agreeingCount7188 = fan7273.agreeingCount,
                            )
                            PipelineHealthCollector.labelInc("ENTRY_HYDRATION_FANOUT_PRICED_7273")
                            if (fan7273.corroborated) PipelineHealthCollector.labelInc("ENTRY_HYDRATION_FANOUT_CORROBORATED_7273")
                        } catch (_: Throwable) {}
                    } else if (fan7273 != null) {
                        try { PipelineHealthCollector.labelInc("ENTRY_HYDRATION_FANOUT_CONTESTED_7273") } catch (_: Throwable) {}
                    } else {
                        try { PipelineHealthCollector.labelInc("ENTRY_HYDRATION_FANOUT_EMPTY_7273") } catch (_: Throwable) {}
                    }
                }
                tryFallbackPriceData(mint, ts)
            } catch (ce: CancellationException) {
                throw ce
            } catch (t: Throwable) {
                try { ForensicLogger.lifecycle("ENTRY_HYDRATION_ERROR_6647", "mint=${mint.take(10)} error=${t.javaClass.simpleName}:${t.message?.take(80)}") } catch (_: Throwable) {}
            } finally {
                entryHydrationPending6647.remove(mint)
            }
        }
    }

